\label{main theorem}
    Let $p$ be a prime number and $m,r$ be positive integers with $m\ge 3$ and {$r\geq r_p$, where $r_p = 1$ (resp. $r_p = 2$) if $p\geq 3$ (resp. $p=2$).} Suppose that
    \[
        f(m)  < 2\left(r+\dfrac{1}{p-1}\right)\log p.
    \]
    \begin{enumerate}
      \item If $m$ is even, then the $m/2$ following $p$-adic numbers
        \[
            1,\zeta_p(3,p^{-r}), \zeta_p(5,p^{-r}), \ldots,\zeta_p(m-1,p^{-r})\textrm{ are linearly independent over $\mathbb{Q}$}.
        \]
      \item If $m$ is odd, then $1$ together with the $(m-1)/2$ following $p$-adic numbers
        \begin{align*}
            \zeta_p\big(s,\tfrac{1}{p^r}+\tfrac{1}{2}\big)-\zeta_p\big(s,\tfrac{1}{p^r}\big) \qquad (s=2,4,6,\dots,m-1)
        \end{align*}
        are linearly independent over $\mathbb{Q}$
    \end{enumerate}

The Laurent series involved in Theorem~\ref{main theorem} satisfy the functional equation
    \begin{align*}
        f(z) = f(1-z),
    \end{align*}
    which is at the heart of our study. Our constructions could be adapted to deal with Laurent series satisfying
    \begin{align*}
        f(z) = -f(1-z).
    \end{align*}
    There does not seem to be any real difficulty in doing so, some dual statements are even established throughout our article. This would, for example, lead to linear independence results of values $\zeta_p(s,x)$ with $s$ \textrm{even}. We did not include this study in our article in order to keep it of reasonable size, and since we were ultimately more interested in odd $p$-adic Riemann zeta values (which are connected to odd values of the $p$-adic Hurwitz Riemann function), rather than its even values.

If $p\geq 3$ and $x\in \mathbb{Z}_p^\times$, then           




    $\omega(x)$ is the unique $(p-1)$-th root of unity that is congruent to $x$ modulo $p$ (see \cite[Theorem~33.4]{Shi}). We easily deduce from the above that
    \begin{align*}

        \omega(p^{-a}+y) = p^{-a} \omega(1+yp^{a}) = p^{-a} \in \mathbb{Q}
    \end{align*}
    for each integer $a\geq 0$ and each $y\in\mathbb{Q}_p$ with $|y|_p < p^a$. In the special case $p=2$, either $x$ or $-x$ is congruent to $1$ modulo $4 = q_p$, and we set $\omega(x) = \pm 1$, so that $x$ is congruent to $\omega(x)$ modulo $4$. See \cite[Section 2]{KP2} for more details.

\label{def: p-adic Hurwitz zeta function}
    For $x\in\mathbb{Q}_p$ and $s\in \mathbb{C}_p\setminus\{1\}$ with $|x|_p\geq q_p$ and  $|s|_p<q_pp^{-1/(p-1)}$, we define $\zeta_p(s,x)$ by the formula
    \begin{align*}
        \zeta_p(s,x) =                                                 
        \frac{\langle x\rangle^{1-s}}{s-1} \sum_{k\geq 0} \binom{1-s}{k}B_kx^{-k}.
    \end{align*}

{\rm{ \cite[Proposition~11.5.6.]{C}}} \label{expansion zeta_p}
Let $s\ge2$ be an integer and $x\in \mathbb{Q}_p$ with $|x|_p\geq q_p$. Then one has
\begin{equation}
    \label{eq: link zeta_p and derivative of G_p}
    \omega(x)^{1-s}\zeta_p(s,x) = \dfrac{(-1)^{s+1}}{(s-1)!} \sum_{k=s-2}^{\infty}(k-s+3)_{s-2}B_{k-s+2}\cdot\frac{(-1)^{k+1}}{x^{k+1}}.
\end{equation}

In the case $f(z) = -\log(1-1/z)$, the map $\varphi_f$ is simply the operator $P(t)\mapsto \int_0^1 P(u)du$, which is the reason why we called it $f$-integration transform in previous work. {The way we use these transforms and their properties also gives a strong flavor of umbral calculus, hence the new terminology ``umbral transform''.} Given $f\in (1/z)\cdot K[[1/z]]$, the map $\varphi_f$ extends naturally in a $K[z]$-linear map $\varphi_f: K[z,t]\rightarrow K[z]$. Given a formal series of the form
    \begin{align*}
         F(z,t) = \sum_{k = -n}^{\infty} \dfrac{P_k(t)}{z^{k}},
    \end{align*}
    where $n\in\mathbb{Z}$ and $P_k(t)\in K[t]$ for each $k\geq -n$, we also set
    \begin{align*}
        \varphi_f(F(z,t)) = \sum_{k\geq -n} \frac{\varphi_f(P_k(t))}{z^k} \in z^n K[[1/z]].
    \end{align*}
    Writing $1/(z-t) = \sum_{k\geq 1}t^k/z^{k+1}$, this yields the identity
    \begin{align*}
        f(z)=\varphi_f \left(\dfrac{1}{z-t}\right),
    \end{align*}
    ({\it confer} \cite[(6.2) p.60 and (5.7) p.52]{N-S}). 
    Furthermore, for any $P(z)\in K[z]$,
    \begin{align*}
         P(z)f(z)-\varphi_f\left(\dfrac{P(z)-P(t)}{z-t}\right)\in (1/z)\cdot K[[1/z]].
    \end{align*}

Throughout this article, we will use the following operators. We use bold symbols to indicate when a map is defined on the ring $K[t]$ (in order to distinguish them from their analogues defined on $K[z]$ in Section~\ref{section: Modified Mellin transform}). Fix an element $\alpha\in K$.
\begin{itemize}[label=$\bullet$]
    \item $[P]\in {\rm{End}}_{K\text{-lin}}(K[t])$ denotes the multiplication by the polynomial $P \in K[t]$. If there is no ambiguity, we will sometimes omit the brackets.
    \item We denote by $\mathrm{Eval}_{t=\alpha}\in {\rm{Hom}}_K(K[t],K)$ the $\alpha$-evaluation linear form, and by $\boldsymbol{\tau}_{\alpha}\in {\rm{End}}_{K\text{-alg}}(K[t])$ (resp. $\boldsymbol{\Delta}_{\alpha} = \boldsymbol{\tau}_\alpha- [1] \in {\rm{End}}_{K\text{-lin}}(K[t])$) the $\alpha$-shift (resp. $\alpha$-difference) operator. They are given by
        \begin{align*}
            \mathrm{Eval}_{t=\alpha}(P(t)) = P(\alpha), \quad \boldsymbol{\tau}_{\alpha}(P(t)) = P(t+\alpha) \quad \textrm{and} \quad \boldsymbol{\Delta}_\alpha(P(t)) = P(t+\alpha)-P(t),
        \end{align*}
        for each $P(t)\in K[t]$.
    \item For any $f(z)\in K((1/z))$, we denote by $\pi(f(z))$ the unique element of $(1/z)\cdot K[[1/z]]$ such that $f(z)-\pi(f(z)) \in K[z]$. This defines a (surjective) projection map
        \begin{align*}

\label{key prop}
    Let $f(z)\in (1/z)\cdot K[[1/z]]$ and $D\in K[z,\tau_{\alpha}]$. Then, viewing $\varphi_{\pi(D(f))}$ and $\varphi_f\circ D^{*}$ as elements of ${\rm{Hom}}_{K}(K[t],K)$, one has
    \begin{align*}
        \varphi_{\pi(D(f))}=\varphi_f\circ D^{*}.
    \end{align*}

\label{inc}
    Let $f(z)\in (1/z)\cdot K[[1/z]]$ and $D\in K[z,\tau_{\alpha}]\setminus\{0\}$. We have the equivalence:
    \begin{align*}
        D(f(z))\in K[z] \Longleftrightarrow D^{*}(K[t])\subseteq \ker \varphi_f.
    \end{align*}

The \textsl{modified inverse Mellin transform} $\mathfrak{M}^{\rm{Inv}}_K:K[[z]]\longrightarrow (1/z) \cdot K\left[\left[1/z\right]\right]$ is defined by
    \begin{align*}
        \mathfrak{M}^{\rm{Inv}}_K(g)(z) = \sum_{k=0}^{\infty}b_k\left(-\dfrac{1}{z}\right)^{k+1},
    \end{align*}
    for each  $g(z)\in K[[z]]$, where $(b_k)_{k\ge0} \in K^{\mathbb{Z}_{\geq 0}}$ is such that $g(e^z-1)=\sum_{k=0}^{\infty}b_kz^k/k!$. When there is no ambiguity, we simply write $\mathfrak{M}^{\rm{Inv}} = \mathfrak{M}^{\rm{Inv}}_K$

$(${\rm{\cite[Proposition~$3.8$]{KP2}}}$)$ \label{key prop 0}
    For any $f(z), g(z) \in K[[z]]$, one has
    \begin{align*}

        \mathfrak{M}^{\rm{Inv}}\big(f(z)g(z)\big) = \widehat{\mathfrak{M}}^{\mathrm{Inv}}(f(z))\big(\mathfrak{M}^{\rm{Inv}}(g(z)) \big),
    \end{align*}
    where $\widehat{\mathfrak{M}}^{\mathrm{Inv}}_K: K[[z]] \longrightarrow K[[d/dz]]$ is the isomorphism of $K$-algebra defined by $z \mapsto \Delta_1 = \exp(d/dz)-1$.
    This yields the following commutative diagram:
    \begin{align*}
        \begin{CD}
        K[[z]]\times K[[z]] @>{\widehat{\mathfrak{M}}^{\mathrm{Inv}}\times \mathfrak{M}^{\rm{Inv}}} >> K\left[\left[{d}/{dz}\right]\right]\times (1/z)\cdot K \left[\left[1/z\right]\right]\\
        @VV{ }V @VV{ }V\\
        K[[z]] @>\mathfrak{M}^{\rm{Inv}} >> (1/z)\cdot K\left[\left[1/z\right]\right].
        \end{CD}
    \end{align*}

\label{def: Theta_R}
    For a positive integer $s\ge 2$, set
    \begin{align*}
        &\Theta_s(z)=\mathfrak{M}^{\rm{Inv}}\left(\dfrac{\log(1+z)^{s-1}}{z+2}\right) \quad \textrm{and} \quad  R_s(z)=\mathfrak{M}^{\rm{Inv}}\left(\dfrac{\log(1+z)^{s-1}}{z}\right).
    \end{align*}
    We denote the formal umbral transform associated with $\Theta_s$ (resp. $R_s$) by $\varphi_{\Theta_s}$ (resp. $\varphi_{R_s}$).

\label{lem: series expansion Theta_s and R_s}
    Let $s\geq 2$ be an integer.  We have
    \begin{align*}
        R_2(z) = \sum_{k\geq 0} B_k \left(-\frac{1}{z} \right)^{k+1} \quad \textrm{and} \quad \Theta_2(z) = \sum_{k\geq 0} (1-2^{k})B_k \left(-\frac{1}{z} \right)^{k+1}.
    \end{align*}
    More generally, for each integer $s\geq 2$, we have
    \begin{align*}
         R_{s}(z) &= \frac{d^{s-2}}{dz^{s-2}}R_2(z) = \sum_{k=s-2}^{\infty}b_k(s)\left(-\frac{1}{z} \right)^{k+1}, \\
         \Theta_{s}(z) &= \frac{d^{s-2}}{dz^{s-2}}\Theta_2(z) = -\frac{1}{2}\sum_{k=s-2}^{\infty}(2^{k-s+3}-2)b_k(s)\left(-\frac{1}{z} \right)^{k+1},
    \end{align*}
    where $b_k(s) = (k-s+3)_{s-2}B_{k-s+2}$ for each $k\geq s-2$.

The identity for $R_2(z)$ is given by \cite[Lemma 5.2]{KP2}. Set $g(z) = \log(1+z)/(z+2)$, so that $\Theta_2(z) = \mathfrak{M}^{\rm{Inv}}(g)(z)$. Then, using the generating function $F(z,x) = ze^{xz}/(e^z-1)$ of the Bernoulli polynomials given in \eqref{eq: generating function B_k(x)} together with the identity $B_k(1/2) = (1/2^{k-1}-1)B_k$ for each $k\geq 1$, we find
    \begin{align*}
        g(e^z-1) = \frac{z}{e^z+1} = \frac{1}{2}\Big(F(2z,1/2) - F(2z,0) \Big)  = \sum_{k\geq 0}(B_k(1/2)-B_k)2^{k-1}\frac{z^{k}}{k!}  =  \sum_{k\geq 0}(1-2^{k})B_k\frac{z^{k}}{k!}.
    \end{align*}
    The identity for $\Theta_2(z)$ follows from the above and the definition of $\mathfrak{M}^{\rm{Inv}}$. Finally, according to \cite[Lemma 5.2]{KP2}, for any $g\in K[[z]]$, we have $\mathfrak{M}^{\rm{Inv}}(\log(1+z)g(z)) = \frac{d}{dz}(\mathfrak{M}^{\rm{Inv}}(g)(z))$. This yields the expected formulas for $\Theta_s(z)$ and $R_s(z)$.

\label{Remark T,R}
    In \cite{B}, Beukers defines the Laurent series $\Theta(z)$, $R(z)$ and $T(z)$ by
    \begin{align*}
        &\Theta(z)=\sum_{k=0}^{\infty}(2^{k+1}-2)B_k\left(-\dfrac{1}{z}\right)^{k+1}, \quad R(z) = \sum_{k=0}^{\infty}B_k\left(-\dfrac{1}{z}\right)^{k+1} \quad \textrm{and} \quad  T(z)=\sum_{k=0}^{\infty}(k+1)B_k\left(-\dfrac{1}{z}\right)^{k+2}.
    \end{align*}
    Lemma~\ref{lem: series expansion Theta_s and R_s} implies that
    \[
        \Theta(z)=-2\Theta_2(z), \quad R(z) = R_2(z) \quad \textrm{and} \quad T(z)=R_3(z).
    \]

\label{identities}
Let $s\ge 2$ be a positive integer. Then the following identities hold.
   \begin{enumerate}
      \item \label{assertion identities 1}  $\Theta_2(1-z)=\Theta_2(z)$.
      \item \label{assertion identities 2}  $R_{2}(1-z)=-R_2(z)$.
      \item \label{assertion identities 5}  $\Theta_s(z)= 2^{1-s}\cdot \left(R_s\big((z+1)/2\big) - R_s(z/2)\right)$.


      \item \label{assertion identities new} $(\tau_{1}-1)(R_s(z)) = (\tau_{1}+1)(\Theta_s(z)) =\mathfrak{M}^{\rm{Inv}}(\log(1+z)^{s-1}) = (-1)^s (s-1)!/z^s$.




    \end{enumerate}

\label{kernel}
    For each integer $s\ge 2$ we have
    \begin{align*}
        (\boldsymbol{\tau}_{-1}+1)(t^sK[t])\subseteq {\rm{ker}}\,\varphi_{\Theta_s} \quad \textrm{and} \quad (\boldsymbol{\tau}_{-1}-1)(t^sK[t])\subseteq {\rm{ker}}\,\varphi_{R_s}.
    \end{align*}

\label{lem: lem 8.4 extended}
    Let $m\geq 3$ be an integer. For any integer $s\geq 2$, we have
    \begin{align*}
        \ker \varphi_{\Theta_s} = (\boldsymbol{\tau}_{-1}+1)\big( V_s\big) \quad \textrm{and} \quad \ker \varphi_{R_s} = (\boldsymbol{\tau}_{-1}-1)\big(V_s  \big).
    \end{align*}
    where $V_s = \left\langle 1,t,\dots,t^{s-2},t^{s},t^{s+1},\dots\right\rangle_{K}$.

Proposition~\ref{key prop} applied with $D=(\tau_{1}+1)$ (yields the identity $\varphi_{\Theta_s}\circ (\boldsymbol{\tau}_{-1}+1) = \varphi_{(\tau_{1}+1)(\Theta_s)}$. Similarly, we have $\varphi_{R_s}\circ (\boldsymbol{\tau}_{-1}-1) = \varphi_{(\tau_{1}-1)(R_s)}$), and Lemma~\ref{identities}~\ref{assertion identities new} implies
    \begin{align*}
       \varphi_{\Theta_s}\circ (\boldsymbol{\tau}_{-1}+1) = \varphi_{R_s}\circ (\boldsymbol{\tau}_{-1}-1).
    \end{align*}
    The identity $\ker \varphi_{R_s} = (\boldsymbol{\tau}_{-1}-1)\big(V_s \big)$ comes from \cite[Lemma~8.4]{KP2} (with $\alpha=0$, and using $1\in \ker(\boldsymbol{\tau}_{-1}-1)$). Thus $(\boldsymbol{\tau}_{-1}+1)\big(V_s\big) \subseteq \ker \varphi_{\Theta_s}$. This inclusion is actually an equality since $(\boldsymbol{\tau}_{-1}+1)\big(V_s\big)$ is a hyperplane of $K[t]$ (for $\boldsymbol{\tau}_{-1}+1$ is an automorphism of $K[t]$), and $\varphi_{\Theta_s}$ is a non-zero linear form.

\label{cor: expression restricted intersection ker phi}
    Let $m\geq 3$ be an integer. Set $\delta_m = \dim \ker (\boldsymbol{\tau}_{-1}+(-1)^{m+1})$. If $m$ is even (resp. odd) we denote by $S_m$ the set of odd (resp. even) indices in $\{2,\dots,m-1\}$, and by $F_s$ the Laurent series $R_s$ (resp. $\Theta_s$) for each $s\in S_m$. Then
    \begin{align*}
        \bigcap_{s\in S_m} \ker \varphi_{F_s} = \boldsymbol{p}_{1}\big(K[t]_{\leq m-1-\delta_m}\big) + (\boldsymbol{\tau}_{-1}+(-1)^{m+1})\big(t^m K[t]\big).
    \end{align*}

Fix an integer $m\geq 3$. We first suppose that $m$ is odd. Using Lemma~\ref{lem: lem 8.4 extended} and the fact that $\boldsymbol{\tau}_{-1}+1$ is an automorphism of $K[t]$, we obtain
    \begin{align*}
        \bigcap_{s\in S_m} \ker \varphi_{\Theta_s} =  (\boldsymbol{\tau}_{-1}+1)\Big( \bigcap_{s\in S_m} V_s \Big) = (\boldsymbol{\tau}_{-1}+1)\big(V\big) + (\boldsymbol{\tau}_{-1}+1)\big(t^m K[t]\big),
    \end{align*}
    where $V = \left\langle 1,t^2,\dots,t^{m-1}\right\rangle_{K} = \boldsymbol{\lambda}_1(K[t]_{\leq m-1})$. The conclusion follows from the first identity of \eqref{eq inter: identity op easy} (with $\varepsilon=1$) together with $(\boldsymbol{\tau}_{-1}+1)(K[t]_{\leq m-1}) = K[t]_{\leq m-1}$.\\
    Suppose now that $m\geq 3$ is even. Let us first prove that
    \begin{align} \label{eq inter: computation small inter for Ker phi_R}
        W_m:=  \bigcap_{s\in S_m} (\boldsymbol{\tau}_{-1}-1)(V_s) = (\boldsymbol{\tau}_{-1}-1)\Big(tK[t] \cap \bigcap_{s\in S_m} V_s \Big).
    \end{align}
    The inclusion $\supseteq$ is clear. To prove the direct inclusion, fix $P(t) \in W_m$. Since $(\boldsymbol{\tau}_{-1}-1)(K) = \{0\}$, for each $s\in S_m$, there exists $Q_s\in V_s \cap tK[t]$ such that $P = (\boldsymbol{\tau}_{-1}-1)(Q_s)$. Given $s,s' \in S_m$, we deduce that $Q_s-Q_{s'} \in \ker (\boldsymbol{\tau}_{-1}-1) \cap tK[t] = \{0\}$, and therefore $Q_s = Q_{s'}$. Consequently, there exists $Q(t)\in tK[t]$ such that  $P(t) = (\boldsymbol{\tau}_{-1}-1)(Q(t))$ and $Q(t)\in V_3\cap V_5\cap \cdots \cap V_{m-1}$, hence \eqref{eq inter: computation small inter for Ker phi_R}. Note that $\ker \varphi_{R_3} \cap \ker \varphi_{R_5} \cap \cdots \cap \ker \varphi_{R_{m-1}}$ is equal to $W_m$ by Lemma~\ref{lem: lem 8.4 extended}. Finally, we have
    \begin{align*}
        tK[t] \cap  V_3\cap V_5\cap \cdots \cap V_{m-1} = V + t^m K[t],
    \end{align*}
    where $V = \left\langle t,t^3,\dots,t^{m-1}\right\rangle_{K} = \boldsymbol{\lambda}_{-1}(K[t]_{\leq m-1})$. The space $(\boldsymbol{\tau}_{-1}-1)(V)$ is equal to $\boldsymbol{p}_{1} \circ (\boldsymbol{\tau}_{-1}-1)(K[t]_{\leq m-1})$ thanks to the first identity of \eqref{eq inter: identity op easy}. We conclude easily by noticing that $(\boldsymbol{\tau}_{-1}-1)(K[t]_{\leq m-1}) = K[t]_{\leq m-2}$.

\label{key expansion R_s and Theta_s}
    Let $t\geq  0$ be an integer. We have
    \begin{align*}
        R_{3+2t}(z) = (-1)^{t+1}\sum_{k=t}^{\infty}\dfrac{b_k(2k+1)!}{(z)_{k+1}(1-z)_{k+1}}, \quad \textrm{where } b_k = \sum_{\substack{ j_0,\dots,j_t \geq 0 \\ j_0+\cdots + j_t = k-t}} \prod_{i=0}^{t} \frac{j_i!^2}{(j_i+1)(2j_i+1)!}, \\
        2\Theta_{2+2t}(z) = (-1)^{t+1}\sum_{k=t}^{\infty}\dfrac{c_k(2k+1)!}{(z)_{k+1}(1-z)_{k+1}}, \quad \textrm{where } c_k = \sum_{\substack{ j_0,\dots,j_t \geq 0 \\ j_0+\cdots + j_t = k-t}}(j_t+1) \prod_{i=0}^{t} \frac{j_i!^2}{(j_i+1)(2j_i+1)!}.
    \end{align*}

\label{explicit expansion}
    Let $g(z)\in K[[z]]$ and set $f(z)=\mathfrak{M}^{\rm{Inv}}(g)(z)$. Suppose that $f(z)\in V_{1}$. Then there exists (a unique) sequence $(a_k)_{k\geq 0}\in K^{\mathbb{Z}_{\geq 0}}$ such that
    \begin{align*}                     
        g(z) = \sum_{k=0}^{\infty}(-1)^{k+1} a_k\dfrac{z^{2k+1}}{(1+z)^{k+1}}  \quad \textrm{and} \quad f(z)=\sum_{k=0}^{\infty}\dfrac{a_k(2k+1)!}{(z)_{k+1}(1-z)_{k+1}}.
    \end{align*}

Let $U^+$ denote the right-hand side of the above equality. Clearly, $U^+ \subseteq U_1$. Now, let $f(z) \in U_1$. If $f(z)\neq 0$, then its order must be even. So, there exists $N\geq 1$ and $a_{N}\in K^\times$ such that $f(z) \in a_N/z^{2N} + (1/z^{2N+1})\cdot K[[1/z]]$. This implies that
    \begin{align*}
        r_N(z) := f(z) - \frac{a_N}{(z)_N(1-z)_N} \in V_{1} \cap \frac{1}{z^{2N+1}}K[[1/z]] = V_{1} \cap \frac{1}{z^{2N+2}}K[[1/z]].
    \end{align*}
    By repeating the process, we construct by induction a sequence $(a_k)_{k\geq N}$ in $K$ such that
    \begin{align*}
        r_M(z) := f(z) - \sum_{k=N}^M\frac{a_k}{(z)_k(1-z)_k} \in V_{1} \cap \frac{1}{z^{2M+2}}K[[1/z]]
    \end{align*}
    tends to $0$ as $n$ tends to $\infty$ (with respect to the $(1/z)$-adic topology on $K[[1/z]]$), hence $f(z)\in U^+$.

Recall that by definition (see Section~\ref{subsection: theta_s and R_s}), for each integer $t \geq 0$, we have
\begin{align*}
        R_{3+2t}(z)=\mathfrak{M}^{\rm{Inv}}\left(\dfrac{\log(1+z)^{2+2t}}{z}\right) \quad \textrm{and} \quad  \Theta_{2+2t}(z)=\mathfrak{M}^{\rm{Inv}}\left(\dfrac{\log(1+z)^{1+2t}}{z+2}\right).
    \end{align*}
Using the following identities,
\begin{align*}
    \log(1+z)^2 = -\sum_{k\geq 0} \frac{a_k}{(k+1)} Z^{k+1} \quad \textrm{and} \quad \frac{\log(1+z)}{z+2} = -\frac{1}{2z}\sum_{k\geq 0}a_k  Z^{k+1},
\end{align*}
where $a_k = k!^2/(2k+1)!$ and $Z = -z^2/(1+z)$, it follows that
\begin{align}
    \dfrac{\log(1+z)^{2+2t}}{z} & = (-1)^{t+1}\sum_{k\geq t}(-1)^{k+1} b_k \dfrac{z^{2k+1}}{(1+z)^{k+1}}, \label{eq: expansion g_s m even} \\
    \dfrac{\log(1+z)^{1+2t}}{z+2}  & = \frac{(-1)^{t+1}}{2}\sum_{k\geq t} (-1)^{k+1} c_k \dfrac{z^{2k+1}}{(1+z)^{k+1}}, \label{eq: expansion g_s m odd}
\end{align}
{where the coefficients $b_k$ and $c_k$ are defined in Proposition~\ref{key expansion R_s and Theta_s}. 
We conclude by Lemma~\ref{image of M}.

\label{value phif}
    Consider a Laurent series $f(z)\in (1/z)\cdot K[[1/z]]$.
    \begin{enumerate}[label=(\alph*)]
      \item Suppose that $f(z)\in V_{1}$ and write $f(z)=\sum_{k\geq 0}\dfrac{a_k}{(z)_{k+1}(1-z)_{k+1}}$. Then
        for each integer $j\geq 0$:
        \begin{enumerate}
            \item \label{lem value phif: item 1} $\varphi_f\left((t)_j(1-t)_j\right)=0$,
            \item \label{lem value phif: item 2} $\varphi_f\left((t)_{j+1}(1-t)_j\right)=-a_j$,
            \item \label{lem value phif: item 3} $\varphi_f\left((t)_j(1-t)_{j+1}\right)=a_j$.
        \end{enumerate}
      \item Suppose that $f(z)\inV_{-1}$ and write $f(z)=\sum_{k\geq 0}\dfrac{a_k}{(2z-1)(z)_{k}(1-z)_{k}}$. Then for each integer $j\geq 0$:
        \begin{enumerate}
            \setcounter{enumii}{3}
            \item \label{lem value phif: item 4} $\varphi_f\left((2t-1)(t)_j(1-t)_j\right)=0$,
            \item \label{lem value phif: item 5} $\varphi_f\left((t)_{j+1}(1-t)_{j+1}\right)= a_j/2$.
        \end{enumerate}
    \end{enumerate}

\label{sub ker}
    Let $f(z)\in (1/z)\cdot K[[1/z]]$. Suppose that $f(z)\inV_{1}$ (resp. $f(z)\inV_{-1}$). Then
    \begin{enumerate}
        \item \label{item: cor: sub ker:1}  $W_{1}\subseteq \ker\,\varphi_f$ (resp. $W_{-1}\subseteq \ker\,\varphi_f$),
        \item \label{item: cor: sub ker:2} $f(z)=-\dfrac{1}{2}{\displaystyle{\sum_{k=0}^{\infty}}}\dfrac{\varphi_f((2t-1)(t)_k(1-t)_{k})}{(z)_{k+1}(1-z)_{k+1}}$ (resp. $f(z)=2{\displaystyle{\sum_{k=0}^{\infty}}}\dfrac{\varphi_f((t)_{k+1}(1-t)_{k+1})}{(2z-1)(z)_{k+1}(1-z)_{k+1}}$).
    \end{enumerate}

The equivalence of \ref{prop: pade cond: item 1} and \ref{prop: pade cond: item 2} was established in \cite[Lemma~$2.3$]{Kaw}, and clearly \ref{prop: pade cond: item 2} $\Rightarrow$ \ref{prop: pade cond: item 3}. It remains to prove that~\ref{prop: pade cond: item 3} $\Rightarrow$ \ref{prop: pade cond: item 2}. First, observe that the set of polynomials
    \[
        \{(t)_k(1-t)_k ; 0\le k\le n-1\}\cup \{A_k(t); k=1,3,\ldots,2n-1\}
    \]
    forms a basis of the $K$-vector space $K[t]_{\le 2n-1}$. Fix $s\in\{1,\dots,m\}$. Since $P\in W_{1}$, Corollary~\ref{sub ker} implies that $(t)_k(1-t)_kP(t)$ belongs to $\ker \varphi_{f_s}$ for each $k\geq 0$. Hence, the equivalence
    \begin{align*}
        \varphi_{f_s}(t^kP(t))=0 \ \text {for } 0\le k \le 2n-1 \Longleftrightarrow
        \varphi_{f_s}(A_k(t)P(t))=0 \ \text {for } \ k=1,3,\ldots,2n-1.
    \end{align*}

\label{def: construction Pade approximants, choice of A_ell}
    Let $n\in \mathbb{Z}_{\geq 0}$. For $\ell=0,\dots,M:= \lfloor (m-1)/2 \rfloor$ and $s=2,\dots,m-1$, define
    \begin{align*}
        P_{m,n,\ell}(z) &= D_{m,n}\big(A_{\ell}(z)\big), \\
        Q_{m,n,s,\ell}(z) &= \varphi_{s}\left( \dfrac{P_{m,n,\ell}(z) - P_{m,n,\ell}(t)}{z - t} \right), \\
        \mathfrak{R}_{m,n,s,\ell}(z) &= P_{m,n,\ell}(z)F_s(z) - Q_{m,n,s,\ell}(z), \\
        \boldsymbol{p}_{m,n,\ell}(z) &= {}^t\!\big(P_{m,n,\ell}, Q_{m,n,s_1,\ell}, \dots, Q_{m,n,s_M,\ell} \big),
    \end{align*}
    where
    \begin{align*}
        n!^{m-1} A_\ell(z) =
        \begin{cases}
            (z-n/2)_\ell (1-z-n/2)_\ell & \textrm{if $m$ is even},\\
            (z-\ell)_{2\ell} & \textrm{if $m$ is odd}.
        \end{cases}
    \end{align*}

\label{Pade}
    Let $m,n \in \mathbb{Z}_{\geq 0}$, with $m \geq 3$, and let $A(z) \in K[z]\cap V_1$.  For $s=2,\dots,m-1$, define
    \begin{align*}
        P(z) := D_{m,n}(A(z)),\quad Q_s(z) := \varphi_{s} \left( \frac{P(z) - P(t)}{z - t} \right) \quad \textrm{and} \quad \mathfrak{R}_s(z) := P(z)F_s(z) - Q_s(z).
    \end{align*}
    \begin{enumerate}
    \item \label{item:Thm Pade:1} Assume $m$ is odd. Then $\deg P = (m-1)n + \deg A$, and the vector of polynomials $\big(P(z), Q_2(z),Q_4(z),\dots,Q_{m-1}\big)$ forms a Pad\'{e}-type approximant of weight $2n$ to the $\frac{m-1}{2}$ tuple {$\big(\Theta_2(z), \Theta_4(z), \ldots, \Theta_{m-1}(z)\big)$}.
    \item \label{item:Thm Pade:2} Assume $m$ is even. Then $\deg P = (m - 2)n + \deg A$, and the vector of polynomials $\big(P(z), Q_3(z),Q_5(z),\dots,Q_{m-1}\big)$ forms a Pad\'{e}-type approximant of weight $2n$ to the $\frac{m-2}{2}$ tuple {$\big(R_3(z), R_5(z), \ldots, R_{m-1}(z)\big)$}.
    \item \label{item:Thm Pade:3} For each $s = 2, 3, \ldots, m - 1$, we have the explicit expansion
        \[
            \mathfrak{R}_s(z) = -\frac{1}{2} \sum_{k = n}^\infty n! \binom{k}{n} \frac{ \varphi_{s}(C_k(t)) }{(z)_{k+1}(1 - z)_{k+1}}.
        \]
        where $C_k(t) = (2t+n-1) (t+n)_{k-n}(1 - t)_{k-n} (t)^m_n A(t + n/2)$.
    \end{enumerate}

\leavevmode
    \begin{itemize}
        \item In the case $m = 3$ and $A(z) = 1$, the polynomial $P(z)$ coincides with a case studied by Beukers~\cite[Section~6]{B}, where it appears in terms of a continuous dual Hahn polynomial (see also~\cite{R2}).
        \item In the case $m = 4$ and $A(z) = 1$, the polynomial $P(z)$ has been investigated by Pr\'{e}vost~\cite[Section~3.2]{P} (see also~\cite[Section~10]{B}), where it is identified as a Wilson polynomial.
    \end{itemize}

\label{thm:expansion}
    We keep the notation and hypotheses of Theorem~\ref{Pade}. Let $\ell\in\mathbb{Z}_{\geq 0}$ be such that $\deg(A) = 2\ell$. Then $P(z)\in V_1\cap K[z]$ and there exists $(p_k(n))_{0\leq k\leq N}\in K^{N+1}$, where $N=Mn+\ell$, such that
    \begin{align*}
        P(z) = \sum_{k=0}^{N} p_k(n) \frac{(z)_k(1-z)_k}{k!^2}.
    \end{align*}
    Furthermore, for each $s\in S_m$, we have
    \begin{align}
        Q_{s}(z) & = \sum_{k=1}^{N}p_{k}(n)\sum_{j=0}^{k-1} \frac{b_{s,j}}{j+1} \binom{2j+1}{j+1} \binom{k}{j+1}^{-2} \dfrac{(z+j+1)_{k-j-1}}{(k-j-1)!} \dfrac{(2+j-z)_{k-j-1}}{(k-j-1)!}, \label{eq thm: expansion Q_s}  \\
        \mathfrak{R}_{s}(z) & = \dfrac{n!}{2}\sum_{k=n}^{\infty} \binom{k}{n} \dfrac{r_{k,s}}{(z)_{k+1}(1-z)_{k+1}}, \label{eq thm: expansion remainder R_s}
    \end{align}
     where, writing $C_k(t) = (2t+n-1) (t+n)_{k-n}(1 - t)_{k-n} (t)^m_n A(t + n/2)$, we have
    \begin{align*}                
        r_{k,s}=\sum_{j=0}^{mn+2(k-n+\ell)+1}a_{s,j} \cdot \mathrm{Eval}_{t=0}\circ \boldsymbol{\Delta}_{-1}^j (C_{k}(t)).
    \end{align*}

\label{lemma key}
    Let $n,m \in\mathbb{Z}_{\ge 0}$ and set $T_n(t) = (t-n/2)_n\in K[t]$. Then $T_n(t)$ belongs to $W_{1}$ (resp. $W_{-1}$) if $n$ is even (resp. odd), and
    \[
        {\mathbf{R}_{\varepsilon}^n \big(T_n(t)^mW_{1} \big)} \subseteq W_{1}, \quad \textrm{where } \varepsilon = (-1)^{m-1}.
    \]
    More generally,
    \begin{align*}
        \mathbf{R}_{\varepsilon}^k\big(T_n(t)^mW_{1} \big) \subseteq T_{n-k}(t)^m W_{1}, \qquad \textrm{for $k=0,\dots,n$}.
    \end{align*}

\label{key}
        Let $P(t)\in W_{-1}$ and $\varepsilon\in\{1,-1\}$. Define the operator $E = -\mathbf{D}_{-1} \circ \left[\frac{1}{2t-1}\right]$. There exists a sequence of polynomials $(P_i(t))_{i\geq 0}$ in $K[t]$ such that for each integer $n\geq0$,
        \begin{align} \label{eq:prop key}
            [P(t)]\circ \mathbf{R}_{\varepsilon}^n= \mathbf{D}_\varepsilon \circ \left(\sum_{i=0}^{n-1}\boldsymbol{\tau}^i_{1/2}\circ [P_{i}(t)]\circ \mathbf{R}_{\varepsilon}^{n-1-i}\right)+\boldsymbol{\tau}^{n}_{1/2}\circ [ E^n(P(t))].
        \end{align}

First note that by \eqref{eq: basic tau pm tau stabilized subsapces}, we have $E^k(P(t)) \in W_{-1}$ for each integer $k\geq 0$. We construct the polynomial $P_i(t)$ by induction on $i$. A quick computation shows that for any $Q(t)\in K[t]$, we have
    \begin{align*}
        [Q(t)] \circ \mathbf{D}_\varepsilon = \mathbf{D}_\varepsilon \circ[\boldsymbol{\tau}_{1/2}(Q(t))]-\boldsymbol{\tau}_{1/2}\circ[\mathbf{D}_{-1}(Q(t))].
    \end{align*}
    Since $P(t)\in W_{-1}$, there exists $Q(t)\in W_{1}$ such that $P(t) = (2t-1)Q(t)$, and setting $P_0(t) = \boldsymbol{\tau}_{1/2}(Q(t))$, the above equality may be rewritten as
    \begin{align} \label{k=1}
        [P(t)]\circ \mathbf{R}_{\varepsilon} = [Q(t)] \circ \mathbf{D}_\varepsilon = \mathbf{D}_\varepsilon \circ[P_0(t)]+\boldsymbol{\tau}_{1/2}\circ[E(P(t))],
    \end{align}
    which is \eqref{eq:prop key} for $n=1$. Now fix an integer $n\geq 1$ and assume that $P_0(t),\dots,P_{n-1}(t)\in K[t]$ are such that \eqref{eq:prop key} holds. This implies that
    \begin{align*}             
        [P(t)]\circ \mathbf{R}_{\varepsilon}^{n+1} =  \mathbf{D}_\varepsilon \circ \left(\sum_{i=0}^{n-1}\boldsymbol{\tau}^i_{1/2}\circ [P_{i}(t)]\circ \mathbf{R}_{\varepsilon}^{n-i}\right)+\boldsymbol{\tau}^{n}_{1/2}\circ [ E^n(P(t))] \circ \mathbf{R}_{\varepsilon}.
    \end{align*}
    Using \eqref{k=1} with $P(t)$ replaced by $E^n(P(t)) \in W_{-1}$, we find a polynomial $P_n(t)\in K[t]$ such that
    \begin{align*}             
        [ E^n(P(t))] \circ \mathbf{R}_{\varepsilon} = \mathbf{D}_\varepsilon \circ[P_n(t)]+\boldsymbol{\tau}_{1/2}\circ[E^{n+1}(P(t))].
    \end{align*}
    Since $\mathbf{D}_\varepsilon$ and $\boldsymbol{\tau}_{1/2}$ commute, we obtain \eqref{eq:prop key} for $n+1$.

\label{cor key}
        Let $n,m \geq 0$ be integers and $\varepsilon\in\{1,-1\}$, and let $P(t)\in W_{-1}$ and $A(t)\in W_{1}$. Then
        \begin{align*}
            P(t)\mathbf{R}_{\varepsilon}^n {\big(T_n(t)^m A(t) \big)}  \in (1+\varepsilon\boldsymbol{\tau}_{-1}){\big( t^m K[t] \big)} + R(t),
        \end{align*}
        where $R(t) = \boldsymbol{\tau}^{n}_{1/2}\Big( E^n(P(t))T_n(t)^m A(t) \Big)$ and $T_n(t) = (t-n/2)_n\in K[t]$ is defined as in Lemma~\ref{lemma key}. Moreover, $R(t)=0$ if $\deg P(t) < 2n$.

By Proposition~\ref{key}, there exist $P_0(t),\dots,P_{n-1}(t)\in K[t]$ such that
    \begin{align*}
        P(t)\mathbf{R}_{\varepsilon}^n {\big(T_n(t)^m A(t) \big)} & = \mathbf{D}_\varepsilon \left(\sum_{i=0}^{n-1}\boldsymbol{\tau}^i_{1/2}\circ [P_{i}(t)]\circ \mathbf{R}_{\varepsilon}^{n-1-i}\Big(T_n(t)^m A(t) \Big)\right) + R(t) \\
        & \subseteq  (1+\varepsilon \boldsymbol{\tau}_{-1}) \left(\sum_{i=0}^{n-1}\boldsymbol{\tau}_{1/2}^{i+1} \Big(T_{i+1}(t)^m K[t] \Big)\right)  + R(t),
    \end{align*}
    the last inclusion coming from Lemma~\ref{lemma key} and the identity $\mathbf{D}_\varepsilon =  (1+\varepsilon \boldsymbol{\tau}_{-1})\circ\boldsymbol{\tau}_{1/2}$. We conclude by noticing that $\boldsymbol{\tau}^{i+1}_{1/2}(T_{i+1}(t)^m)\in t^m K[t]$ for $i=0,\dots,n-1$. Finally, suppose that $\deg P(t) < 2n$. Since $\deg(E(Q(t)) \leq \deg(Q(t)) -2$ for each $Q(t)\in W_{-1}$, we then have $E^n(P(t)) = 0$.

\label{compute remainder}
    Define the operator $E = -\mathbf{D}_{-1} \circ \left[\frac{1}{2t-1}\right]$ as in Proposition~\ref{key}. Let $k,n$ be integers with $k\ge n \geq 0$. Then
    \begin{align*}
        E^n\big((2t-1)(t)_k(1-t)_k \big)=n!\binom{k}{n}{{(2t-1)}}(t+n/2)_{k-n}(1+n/2-t)_{k-n}.
    \end{align*}

Let $\alpha\in K$ and set $\beta = \alpha+1/2$. A direct computation shows that
    \begin{align*}
        E\big((2t-1)(t+\alpha)_k(1+\alpha-t)_k \big) = k(2t-1)(t+\beta)_{k-1}(1+\beta-t)_{k-1}.
    \end{align*}
    Applying this identity iteratively $n$ times with $\alpha=0,1/2,\ldots,(n-1)/2$, we obtain the expected result.

Lemma~\ref{lemma key} ensures that $P(z)\in V_{1}\cap K[z]$. Combined with \eqref{V^{+},V^{-}} we get  $P(z)F_s(z)\in K((1/z))$. Since $Q_s(z)$ is the polynomial part of this Laurent series (and since $I$ stabilizes $(1/z)\cdot K[[1/z]]$), we deduce that $Q(z)\in V_{1}\cap K[z]$, and $\mathfrak{R}_s(z)\in V_{1}\cap (1/z)\cdot K[[1/z]]$. Corollary~\ref{sub ker}~\ref{item: cor: sub ker:2} yields
    \begin{align*}
        \mathfrak{R}_s(z)=-\dfrac{1}{2}\sum_{k=0}^{\infty}\dfrac{\varphi_{\mathfrak{R}_s}\big((2t-1)(t)_k(1-t)_k\big)}{(z)_{k+1}(1-z)_{k+1}},
    \end{align*}
    Fix $k \geq 0$. It only remains to prove that
        \begin{align*}
            \varphi_{\mathfrak{R}_s}\big((2t-1)(t)_k(1-t)_k)\big)=n!\binom{k}{n}\varphi_{s}\Big({{(2t+n-1)}}(t+n)_{k-n}(1-t)_{k-n} (t)^m_nA(t+n/2)\Big).
        \end{align*}
    Recall that $\pi : K((1/z))\rightarrow  (1/z)\cdot K[[1/z]]$ is the projection defined in Section~\ref{section: f transform}. Set $D= [P(z)]$, so that $D^{*} = [P(t)]$. Then $\mathfrak{R}_s(z)=\pi(P(z)F_{s}(z)) = \pi(D(F_s))$, and Proposition~$\ref{key prop}$ leads us to
    \begin{align*}
        \varphi_{\mathfrak{R}_s}\big((2t-1)(t)_k(1-t)_k)\big)=\varphi_{s}\big((2t-1)(t)_k(1-t)_kP(t)\big).
    \end{align*}
    Since $P(t)=\mathbf{R}_{\varepsilon}^{n}((t-n/2)^m_nA(t))$, where $\varepsilon= (-1)^{m-1}$, we have
    \begin{align*}
        (2t-1)(t)_k(1-t)_kP(t)=[(2t-1)(t)_k(1-t)_k]\circ \mathbf{R}_{\varepsilon}^{n}\big((t-n/2)^m_nA(t)\big).
    \end{align*}
    Combining Corollaries~\ref{kernel} and~\ref{cor key}, we obtain
    \begin{align*}
        \varphi_{s}\big((2t-1)(t)_k(1-t)_kP(t)\big) = \varphi_s\big( \boldsymbol{\tau}^{n}_{1/2}\big( B(t) (t-n/2)^m_nA(t) \big) \big),
    \end{align*}
    where $B(t) = E^n\big((2t-1)(t)_k(1-t)_k\big)$. Using Lemma~\ref{compute remainder}, we finally get
    \begin{align*}
        \boldsymbol{\tau}^{n}_{1/2}\big( B(t)P(t) \big) = n!\binom{k}{n}{{(2t+n-1)}}(t+n)_{k-n}(1-t)_{k-n} (t)^m_nA(t+n/2).
    \end{align*}

Let $f(z)\in V_{1}\cap (1/z)\cdot K[[1/z]]$ and $P(z)\in V_{1}\cap K[z]$ of degree $2N$, and write
    \begin{align*}
        f(z) = \sum_{k=0}^{\infty}\dfrac{a_k(2k+1)!}{(z)_{k+1}(1-z)_{k+1}} \quad \textrm{and} \quad P(z)=\sum_{k=0}^N p_k\dfrac{(z)_{k}}{k!}\dfrac{(1-z)_k}{k!},
    \end{align*}
    with  $a_k,p_j\in K$ for $k\in\mathbb{Z}_{\geq 0}$ and $j=0,\dots,N$. Then one has
    \begin{align*}
    \varphi_f\left(\dfrac{P(z)-P(t)}{z-t}\right)=\sum_{k=1}^{N}p_k\sum_{j=0}^{k-1}\frac{a_j}{j+1}\binom{2j+1}{j+1}\binom{k}{j+1}^{-2}\dfrac{(z+j+1)_{k-j-1}}{(k-j-1)!}\dfrac{(2+j-z)_{k-j-1}}{(k-j-1)!}.
    \end{align*}

\label{cor: key for non-vanishing det}
    Let $m,n\geq 1$ be integers and let $P(t),Q(t),R(t)\in K[t]$ be such that
    \begin{enumerate}
      \item \label{enum: prop clef for non_vanishing det: item 1} $(t)_n^m P(t) = Q(t) + (\boldsymbol{\tau}_{-1}+(-1)^{m+1})(t^m R(t))$;
      \item \label{enum: prop clef for non_vanishing det: item 2}  $\deg Q(t) <  nm + \deg P(t)$;
      \item \label{enum: prop clef for non_vanishing det: item 3} $Q(t)\in \ker \boldsymbol{p}_{-1} = \ker \boldsymbol{q}_{-1,0}$.
    \end{enumerate}
    If $P(t)\in \ker \boldsymbol{q}_{1,n} \setminus\{0\}$, then $\deg P \geq m-\delta_m$, where $\delta_m = \dim \ker (\boldsymbol{\tau}_{-1}+(-1)^{m+1})\in \{0,1\}$.

\label{prop: key for non-vanishing det}
    Let $m,n\geq 1$ be integers. Set $\varepsilon = (-1)^{m+1}$ and $\delta_m = \dim \ker (\boldsymbol{\tau}_{-1}+\varepsilon)\in \{0,1\}$. Suppose that there exist $P(t),Q(t),R(t)\in K[t]$, with $P(t)\neq 0$, satisfying conditions~\ref{enum: prop clef for non_vanishing det: item 1}--\ref{enum: prop clef for non_vanishing det: item 3} of Proposition~\ref{cor: key for non-vanishing det}. Then there exist polynomials $S_{-1},S_0,\dots,S_n\in K[t]$ such that for $k=0,\dots,n$
    \begin{enumerate}[label=(\alph*)]
      \item \label{enum: prop clef for non_vanishing det: item got 1} $S_k(t)\in \ker \boldsymbol{q}_{-1,k-1}$;
      \item \label{enum: prop clef for non_vanishing det: item got 2} $(t+k)_{n-k}^m P(t) + (1-t)^m S_k(t) = S_{k-1}(t+1) \in \ker \boldsymbol{q}_{-1,k}$;
      \item \label{enum: prop clef for non_vanishing det: item got 3} $\deg S_{k}(t) \leq (n-k-1)m + \deg P + \delta_m$.
    \end{enumerate}

For simplicity, write $\boldsymbol{q}_{-1,k} = \boldsymbol{q}_k$. By condition~\ref{enum: prop clef for non_vanishing det: item 2} the degree of $(\boldsymbol{\tau}_{-1}+\varepsilon)(t^m R(t))$ is equal to $\deg \big((t)_n^m P(t)\big) = nm + \deg P$. So, $R$ has degree $(n-1)m + \deg P + \delta_m$. The polynomial
    \begin{align*}
        S(t) = \frac{1}{2}\big(R(t)+ R(-t)\big) \in \ker \boldsymbol{q}_{1}
    \end{align*}
    has degree at most $(n-1)m + \deg P + \delta_m$. We proceed by induction on $k$ starting with $k=0$. Applying $\boldsymbol{p}_{-1}$ to both sides of Eq.~\ref{enum: prop clef for non_vanishing det: item 1}, and using \eqref{eq inter: identity op easy}, we find
    \begin{align*}
        \boldsymbol{p}_{-1}\big( (t)_n^m P(t) ) = \boldsymbol{p}_{-1}\circ (\boldsymbol{\tau}_{-1}+ \varepsilon) \big(t^m R(t)\big) = (\boldsymbol{\tau}_{-1}+ \varepsilon)(t^m S(t)) = -2\varepsilon \boldsymbol{p}_{-1}( (1-t)^m S(1-t)),
    \end{align*}
    where the last equality comes from $S(t-1) = S(1-t)$. Furthermore, $S_0(t) := -2\varepsilon S(t-1)$ belongs to $\ker \boldsymbol{q}_{-1}$ by \eqref{eq: inclusion ker q_k via shift}.  We also have $\deg S_0 = \deg S \leq (n-1)m+\deg P + \delta_m$. By the above, $A(t):=(t)_n^mP(t) + (1-t)^m S_0(t)$ belongs to $\ker \boldsymbol{p}_{-1} = \ker \boldsymbol{q}_0$. Finally, \ref{enum: prop clef for non_vanishing det: item got 2} holds with $S_{-1}(t)=A(t-1)$.

    \medskip

    Suppose now that  for some integer $k$ with $0\leq k < n$ there exists $S_k(t)\in K[t]$ such that \ref{enum: prop clef for non_vanishing det: item got 1}--\ref{enum: prop clef for non_vanishing det: item got 3} hold. Applying $\boldsymbol{q}_k$ to \ref{enum: prop clef for non_vanishing det: item got 2}, we find
    \begin{align*}
        (t+k)_{n-k}^m P(t) - (t+k)^m S_k(1-t-k) = (1-t)_{n-k}^mP(1-t-k)-(1-t)^m S_k(t) \in \ker\boldsymbol{q}_{k}.
    \end{align*}
    Since $(1-t)^m$ divides the right-hand side polynomial (and since $(1-t)$ and $(t+k)$ are coprime), we deduce that there exists $S_{k+1}(t)\in K[t]$ such that
    \begin{align}
        \label{eq inter: relation S_k and S_k+1}
        (t+k+1)_{n-k-1}^m P(t) - S_k(1-t-k) = -(1-t)^m S_{k+1}(t).
    \end{align}
    As $(t+k)^m(1-t)^m S_{k+1}(t) \in \ker \boldsymbol{q}_k$, we also have $S_{k+1}(t)\in \ker \boldsymbol{q}_k$. We infer from \ref{enum: prop clef for non_vanishing det: item got 1} combined with \eqref{eq: inclusion ker q_k via shift} that $S_k(1-t-k) = S_k(t+1) \in \ker \boldsymbol{q}_{k+1}$. So \ref{enum: prop clef for non_vanishing det: item got 1} and \ref{enum: prop clef for non_vanishing det: item got 2} hold with $k$ replaced by $k+1$. Finally, considering the degree of the polynomials involved in \eqref{eq inter: relation S_k and S_k+1} together with \ref{enum: prop clef for non_vanishing det: item got 3}, we obtain
    \begin{align*}
        m + \deg S_{k+1} \leq \max\big\{(n-k-1)m + \deg P, \deg S_k\big\} \leq (n-k-1)m + \deg P + \delta_m.
    \end{align*}
    This concludes the induction step.

\label{cor: non-sing matrix, useful for rec}
    Let $n,m,M\geq 0$ be integers with $m\geq 3$ and $M=\lfloor (m-1)/2 \rfloor$. The $M\times M$ matrix
    \[
        \Big(\varphi_s\big(T_{2n+1}(t)P_{m,n,\ell}(t) \big) \Big)_{\substack{s\in S_m \\ 0\leq \ell < M}}
    \]
    is non-singular.

Define the operation $ E = (\boldsymbol{\tau}_{-1/2} - \boldsymbol{\tau}_{1/2}) \circ \left[\frac{1}{2t-1}\right]$ as in Proposition~\ref{key}. Recall that $P_{m,n,\ell}(z) = \mathbf{R}_{\varepsilon}^n \Big(T_n(t)^m A_\ell(t) \Big)$, where $\varepsilon=(-1)^{m-1}$ (see Definition~\ref{def: construction Pade approximants, choice of A_ell}). By Corollary~\ref{cor key} combined with Corollary~\ref{kernel}, we have, for each $s\in S_m$,
    \begin{align*}
        \varphi_s\big( T_{2n+1}(t)P_{m,n,\ell}(t) \big) = \varphi_s\big(R(t)\big),
    \end{align*}
    where
    \begin{align*}
        R(t) = \boldsymbol{\tau}^{n}_{1/2}\Big( E^n\big(T_{2n+1}(t)\big)T_n(t)^m A_\ell(t) \Big).
    \end{align*}
    Now, notice that, since $T_{2n+1}(t)\in W_{-1}$, the polynomial $E^n(T_{2n+1}(t))$ belongs to $W_{-1}$ and has degree $1$. So, there exists $\lambda\neq 0$ such that  $E^n(T_{2n+1}(t)) = \lambda(2t-1)$. We deduce that
    \begin{align*}
        R(t) = \lambda(2t+n-1)(t)_n^m A_\ell(t+n/2).
    \end{align*}
    We conclude by \eqref{eq: det Omega non nul}.

\label{thm: property of the coeff of P_n}
    For each integer $n,m,\ell\geq 0$ with $n$ even, $m\geq 3$ and $0\leq \ell \leq M:=\lfloor (m-1)/2 \rfloor$, we have
    \begin{align*}
        (-1)^k p_{k,\ell}^{(m)}(n) \in \mathbb{Z}_{>0} \qquad (0\leq k \leq N_\ell).
    \end{align*}
    Furthermore, with the convention $0^0 = 1$, we have
    \begin{align*}
        \limsup_{\substack{n\to\infty \\ \textrm{$n$ even}}} \max_{0 \leq k\leq N_\ell} |p_{k,\ell}^{(m)}(n)|^{1/n} \leq C(m) \qquad \textrm{where } C(m) =
        \begin{cases}
          \displaystyle \left(\frac{(m-1)^2}{2}\right)^{(m-1)/2}  & \textrm{if $m \geq 3$ is odd,} \\
          \displaystyle \frac{m}{2}\left(\frac{(m-2)m}{2}\right)^{(m-2)/2} & \textrm{if $m \geq 2$ is even.}
        \end{cases}
    \end{align*}

\label{prop: rec coeff H^m odd case}
    Let $n,m \geq 0$, with $m$ odd. Then
    \begin{align}\label{eq prop: rec coeff H^m odd case}
        H_{n,0}^{(m)}(z) = \sum_{j=0}^{N^{(m)}} a_j^{(m)}(n)\frac{ T_{n+2j}(z)}{(j)!^2}.
    \end{align}

\label{prop: asymptotic coeff odd case}
    Given an odd integer $m \geq 1$, then setting $M=(m-1)/2$, we have
    \begin{align}\label{eq: asymptotic coeff odd case}
        \limsup_{n\to\infty} \max_{0\leq j\leq N^{(m)}} \big\{|a_j^{(m)}(n)|^{1/n} \big\} \leq (2M)^M M^{M},
    \end{align}
    with the convention $0^0 = 1$.

\label{lem: rec coeff H^m odd case}
    For any integer $n,j \geq 0$, we have
    \begin{align*}
        \left(\frac{T_n(z)}{n!} \right)^2 \cdot \frac{T_{n+2j}(z)}{j!^2} = \binom{n+j}{j}^2 \cdot \sum_{k=j}^{n+j} \binom{n}{k-j} \frac{T_{n+2k}(z)}{k!^2}.
    \end{align*}

Fix an integer $n\geq 0$. Define $F(j,z) = \sum_{k = j}^{n+j} F(j,k,z)$, where
    \begin{align*}
        F(j,k,z)= \binom{n}{k-j}\frac{T_{n+2k}(z)}{k!^2} = \binom{n}{k-j}\binom{z+n/2+k-1}{n+2k}\frac{(n+2k)!}{k!^2}
    \end{align*}
    is hypergeometric with respect to $j$ and $k$ (with the convention that $\binom{x}{i} = 0$ if $i\in\mathbb{Z}_{<0}$). A quick computation ensures that the hypergeometric term
    \begin{align*}
        G(j,k) = \frac{(j-k)k^2}{n+j+1-k} F(j,k,z)
    \end{align*}
    satisfies the relation
    \[
        (n+j+1)^2F(j+1,k,z) +\left(j-z+\frac{n}{2}+1\right)\left(j+z+\frac{n}{2}\right)F(j,k,z) = G(j,k+1) - G(j,k)
    \]
    (this function was found by using Zeilberger's algorithm with Maple, see \cite{ZeilbergerAeqB}). Taking the sum over $k\in\mathbb{Z}$, we get for any integer $j\geq 0$
    \begin{align*}
        F(j+1,z) = \frac{(z-j-n/2-1)(j+z+n/2)}{(n+j+1)^2}F(j,z).
    \end{align*}
    The sequence $(F'(j,z))_{j\geq 0}$ defined by
    \begin{align*}
        F'(j,z) = \left(\frac{T_n(z)}{n!} \right)^2 \cdot \frac{T_{n+2j}(z)}{j!^2}\binom{n+j}{j}^{-2} = \left(\frac{T_n(z)}{n!} \right)^2 \cdot \binom{z+n/2+j-1}{n+2j}\frac{(n+2j)!n!^2}{(n+j)!^2}
    \end{align*}
    satisfies the same recurrence, so there exists $\lambda(z)$ such that $F'(j,z) = \lambda(z) F(j,z)$ for each $j\geq 0$. Moreover, since both $F'(j,z)$ and $F(j,z)$ have degree $3n+2j$ in the variable $z$, the constant $\lambda$ does not depend on $z$. Evaluating at $j=0$ and $z = z_0 :=n/2+1$, we find that $F'(0,z_0) = n! = F(0,z_0)$ (the only non-zero term in the sum defining $F(0,z_0)$ is for $k=0$). We deduce that $F'(j,z) = F(j,z)$ for any integer $j\geq 0$, as expected.

We prove \eqref{eq prop: rec coeff H^m odd case} by induction on $m\geq 1$. For $m=1$, we have $H^{(1)}_{n,0}(z) = T_n(z)$, so it is automatic. Suppose that \eqref{eq prop: rec coeff H^m odd case} holds for a given $m\geq 1$. Then, using Lemma~\ref{lem: rec coeff H^m odd case}, we obtain
    \begin{align*}
        H^{(m+2)}_{n,0} = \left(\frac{T_{n}(z)}{n!}\right)^2H_{n,0}^{(m)} & = \sum_{k=0}^{N^{(m)}} a_k^{(m)}(n) \binom{n+k}{k}^2 \cdot \sum_{j=k}^{n+k} \binom{n}{j-k} \frac{T_{n+2k}(z)}{k!^2} \\
        & = \sum_{j=0}^{N^{(m+1)}} \left( \sum_{k=\max\{0,j-n\}}^{\min\{N^{(m)},j\}} a_k^{(m)}(n) \binom{n+k}{k}^2 \cdot \binom{n}{j-k} \right) \frac{T_{n+2j}(z)}{j!^2},
    \end{align*}
    which, by definition of the coefficients $(a_j^{(m+2)(n)})_j$, is exactly \eqref{eq prop: rec coeff H^m odd case} with $m$ replaced by $m+2$.

Define
    \begin{align*}
        A^{(m)}(n) = \max_{0\leq j \leq N^{(m)}}\left\{a_j^{(m)}(n)\right\} \quad \textrm{and} \quad A_\infty^{(m)} = \limsup_{n\to\infty} A^{(m)}(n)^{1/n}.
    \end{align*}
    Given $n\geq 0$, we have
    \begin{align*}
        A^{(m+2)}(n) \leq \sum_{j=0}^{N^{(m+2)}} a_j^{(m+2)}(n) & = \sum_{j=0}^{N^{(m+2)}}\sum_{k=\max\{j-n,0\}}^{\min\{j,N^{(m)}\}} a_k^{(m)}(n) \binom{n+k}{k}^2\binom{n}{j-k} \\
        & = \sum_{k=0}^{N^{(m)}} a_k^{(m)}(n) \binom{n+k}{k}^2 \cdot \sum_{j=k}^{n+k} \binom{n}{j-k} \\
        & \leq A^{(m)}(n) 2^n (N^{(m)}+1)\binom{n+N^{(m)}}{n}^2,
    \end{align*}
    since $\sum_{\ell}\binom{n}{\ell} = 2^\ell$ and since $k\mapsto \binom{n+k}{k}$ is increasing. Using Stirling's formula, we deduce that
    \begin{align*}
        A_\infty^{(m+2)} \leq  2\left(\frac{(1+M_m)^{1+M_m}}{M_m^{M_m}}\right)^2 A_\infty^{(m)},
    \end{align*}
    where $M_m = N^{(m)}/n = (m-1)/2$. By induction, we get
    \begin{align*}
        A_\infty^{(m)} \leq  2^{M_m} \prod_{b=0}^{M_m-1}\left(\frac{(1+b)^{1+b}}{b^{b}}\right)^2 =  2^{M_m} M_m^{2M_m}.
    \end{align*}

\label{prop: rec coeff H^m even case}
    Let $n,m \geq 0$, with $m\geq 2$ even. Then
    \begin{align}\label{eq prop: rec coeff H^m even case}
        H_{n,0}^{(m)}(z) = \sum_{j=0}^{N^{(m)}}  a_j^{(m)}(n)\frac{U_{n+j}(z)}{j!(n+j)!}.
    \end{align}

\label{prop: asymptotic coeff even case}
    For any even positive integer $m$, writing $M=(m-2)/2$, we have
    \begin{align}\label{eq: asymptotic coeff even case}
        \limsup_{n\to\infty} \max_{0\leq j\leq N^{(m)}}|a_j^{(m)}(n)|^{1/n} \leq (2M)^M(M+1)^{M+1},
    \end{align}
    with the convention $0^0 = 1$.

\label{lem: rec coeff H^m even case}
    Let $\alpha$ be an indeterminate. For an integer $k\geq 0$, we define
    \begin{align*}
        S^{(\alpha)}_k(z) = S(k) = (-1)^k\frac{(z)_k(1-z+\alpha)_k}{k!^2} = \binom{-z}{k}\binom{k-z+\alpha}{k}.
    \end{align*}
    Let $k,\ell\geq 0$ be integers. Then
    \begin{align*}
        S_k(z)S_\ell(z) = \sum_{j=\max\{k,\ell\}}^{k+\ell} \binom{k+\ell+\alpha}{k+\ell-j} \binom{j}{k} \binom{j}{\ell}S_j(z).
    \end{align*}
    In particular
    \begin{align}\label{eq lem: product of U_k}
        \frac{U_k(z,n)}{k!^2}\frac{U_\ell(z,n)}{\ell!^2} = \sum_{j=\max\{k,\ell\}}^{k+\ell} \binom{k+\ell-n}{k+\ell-j} \binom{j}{k} \binom{j}{\ell} \frac{U_j(z,n)}{j!^2}.
    \end{align}

We have to prove that $A_k = B_k$, where
    \begin{align*}
        A(k,\ell) &:= \binom{-z}{k}\binom{k-z+\alpha}{k}\binom{-z}{\ell}\binom{\ell-z+\alpha}{\ell}, \\
        B(k,\ell) &:= \sum_{j\in\mathbb{Z}} F(k,\ell,j),\qquad \textrm{where } F(k,\ell,j) = \binom{k+\ell+\alpha}{k+\ell-j} \binom{j}{k} \binom{j}{\ell}\binom{-z}{j}\binom{j-z+\alpha}{j}
    \end{align*}
    (with the convention that $\binom{z}{i}=0$ for each $i\in\mathbb{Z}_{<0}$). Note that the function $F(k,\ell,j)$ is hypergeometric with respect to $k$, $\ell$ and $j$, and $F(k,\ell,j) = F(\ell,k,j)$. Using Zeilberger's algorithm (\cite{ZeilbergerAeqB}), we find that
    \begin{align*}
        (k+1)^2F(k+1,\ell,j) + (z+k)(k+1+\alpha-z)F(k,\ell,j) = G(k,\ell,j+1)-G(k,\ell,j),
    \end{align*}
    where
    \[
        G(k,\ell,j):= -\frac{(j+\alpha)(j-k)(j-\ell)}{k+\ell+1-j}F(k,\ell,j).
    \]
    Taking the sum over $j\in\mathbb{Z}$, this shows that $B(k,\ell,z)$ satisfies the order one recurrence relation
    \begin{align*}
        (k+1)^2B(k+1,\ell) + (z+k)(k+1+\alpha-z)B(k,\ell) = 0.
    \end{align*}
    By symmetry, we also have
    \begin{align}\label{eq proof: rec symmetry in l}
        (\ell+1)^2B(k,\ell+1) + (z+\ell)(\ell+1+\alpha-z)B(k,\ell) = 0.
    \end{align}
    A very short computation shows that $(A(k,\ell))_k$ satisfies the same recurrence, so $A(k,\ell) = B(k,\ell)$ if and only if $A(0,\ell) = B(0,\ell)$. Now, taking $k=0$ in \eqref{eq proof: rec symmetry in l}, we obtain
    \begin{align*}
        (\ell+1)^2B(0,\ell+1) + (z+\ell)(\ell+1+\alpha-z)B(0,\ell) = 0,
    \end{align*}
    a relation that the sequence $(A(0,\ell))_\ell$ also satisfies. So $A(0,\ell) = B(0,\ell)$ is and only if $A(0,0) = B(0,0)$, which is trivially true.

    \medskip

    Finally, \eqref{eq lem: product of U_k} is a direct consequence of the identity
    \begin{align*}
       k!^2 S^{(-n)}_k\left(z -\frac{n}{2} \right) = U_k(z,n).
    \end{align*}
    obtained by taking $\alpha = -n$ and by shifting the variable $z$ by $-n/2$.

We proceed by induction on $m$. For $m=2$, this is trivial since $U_n(z,n) = T_n(z)^2$. Suppose that \eqref{eq prop: rec coeff H^m even case} holds for an even integer $m\geq 2$. Then, by \eqref{eq lem: product of U_k} of Lemma~\ref{lem: rec coeff H^m even case}, we have
    \begin{align*}
        H_{n,0}^{(m+2)} = \frac{U_n(z)}{n!^2} H_{n,0}^{(m)} & = \sum_{k=0}^{N^{(m)}} a_k^{(m)}(n)\frac{U_n(z)}{n!^2}\frac{ U_{n+k}(z)}{k!(n+k)!} \\
        & = \sum_{k=0}^{N^{(m)}} \frac{(n+k)!}{k!} a_k^{(m)}(n) \sum_{j=n+k}^{2n+k} \binom{n+k}{2n+k-j} \binom{j}{n} \binom{j}{n+k}\frac{U_j(z)}{j!^2}.
    \end{align*}
    Now, notice that
    \begin{align*}
        \frac{(n+k)!}{k!}\binom{j}{n}\frac{U_j(z)}{j!^2} = \binom{n+k}{n}\frac{U_j(z)}{(j-n)!j!},
    \end{align*}
    hence
        \begin{align*}
        H_{n,0}^{(m+2)}  & = \sum_{j=n}^{N^{(m+1)}+n}  \left(\sum_{k=\max\{0,j-2n\}}^{\min\{j-n,N\}}a_k^{(m)}(n)  \binom{n+k}{n} \binom{n+k}{j-n} \binom{j}{n+k}\right) \frac{U_j(z)}{(j-n)!j!},    

    \end{align*}
    and we conclude by re-indexing from $j=0$ to $N^{(m)}$.

Define
    \begin{align*}
        A^{(m)}(n) = \max_{0\leq j \leq N^{(m)}}\left\{a_j^{(m)}(n)\right\} \quad \textrm{and} \quad A_\infty^{(m)} = \limsup_{n\to\infty} A^{(m)}(n)^{1/n}.
    \end{align*}
    Given $n\geq 0$, we have
    \begin{align*}
         A^{(m+2)}(n) \leq \sum_{j=0}^{N^{(m+2)}} a_j^{(m+2)}(n) & = \sum_{j=0}^{N^{(m+2)}} \sum_{k=\max\{0,j-n\}}^{\min\{j,N^{(m)}\}} a_k^{(m)}(n) \binom{n+k}{n} \binom{n+k}{j}  \binom{n+j}{n+k} \\
         & =  \sum_{k=0}^{N^{(m)}} a_k^{(m)}(n) \binom{n+k}{n} \sum_{j=0}^{k} \binom{n+k}{j}  \binom{n+j}{n+k}.
    \end{align*}
    Now, note that
    \begin{align*}
        \binom{n+k}{j}  \binom{n+j}{n+k} = \binom{n+j}{n}  \binom{n}{j-k} \leq 2^n \binom{n+j}{n}.
    \end{align*}
    Since $t\mapsto \binom{n+t}{n}$ is increasing, we deduce that
    \begin{align*}
        A^{(m+2)}(n) & \leq   2^n A^{(m)}(n)  \sum_{k=0}^{N^{(m)}} \binom{n+k}{n} \sum_{j=k}^{n+k}\binom{n+j}{n} \\
         & \leq 2^n (N^{(m)}+1) A^{(m)}(n) \binom{N^{(m)}+n}{n} \binom{N^{(m)}+2n}{n}.
    \end{align*}
    Using Stirling's formula and writing $M_m = N^{(m)}/n = (m-2)/2$, this yields
    \begin{align*}
        A_\infty^{(m+2)} & \leq   2 \frac{(M_{m+2}+1)^{M_{m+2}+1}}{(M_{m+2}-1)^{M_{m+2}-1}}A_\infty^{(m)}
    \end{align*}
    (since $M_{m+2} = M_m+1$). By induction, we get
    \begin{align*}
        M_\infty^{(m)} & \leq   2^{M_m}\prod_{b=1}^{M_m} \frac{(b+1)^{b+1}}{(b-1)^{b-1}} = 2^{M_m}M_m^{M_m}(M_m+1)^{M_m+1}.
    \end{align*}

Once again, \eqref{eq: asymptotic coeff even case} is not optimal starting $m = 4$. It is possible to get more precise results using Zeilberger's algorithm. For example, for $m=4$, since $N^{(2)} = 0$, we have the explicit formula
\begin{align*}
    a_j^{(4)}(n) = \binom{n}{j}  \binom{n+j}{n} \qquad (0\leq j \leq n),
\end{align*}
and Zeilberger's algorithm ensures that $F(j) = \sum_{j=0}^n  a_j^{(4)}(n)$ satisfies a linear recurrence of order $2$, whose characteristic polynomial is $(x+1)(x^2-6x+1)$. By Poincaré-Perron theorem, we deduce that
\begin{align*}
    M_\infty^{(4)} = 3+2\sqrt 2 = 5.828\cdots
\end{align*}
while Proposition~\ref{prop: asymptotic coeff even case} yields $M_\infty^{(4)} \leq 8$.

\label{prop: rec coeff H^m even case gen case}
    Let $m, M$ be integers with $m\geq 2$ even and $M=(m-2)/2$. Then, for any $\ell$ with $0 \leq \ell \leq M$, and any integer $n\geq M$, there exist coefficients $(a_{j,\ell}^{(m)}(n))_{0\leq j \leq N_\ell}$, where $N_\ell = Mn+\ell$, such that
    \begin{align*}                                             
        H_{n,\ell}^{(m)}(z) = \sum_{j=0}^{N_\ell}  a_{j,\ell}^{(m)}(n)\frac{U_{n+j}(z)}{j!(n+j)!}.
    \end{align*}
    Furthermore, for $j=0,\dots,N_\ell$, we have $(-1)^\ell a_{j,\ell}^{(m)}(n) \in \mathbb{Z}_{>0}$ and
    \begin{align*}
        \limsup_{n\to\infty} \max_{0\leq j\leq N_\ell}|a_{j,\ell}^{(m)}(n)|^{1/n} \leq \limsup_{n\to\infty} \max_{0\leq j\leq N_\ell} \big\{|a_{j}^{(m)}(n)|^{1/n}\big\} \leq (2M)^M(M+1)^{M+1}.                                                     
    \end{align*}

\label{prop: rec coeff H^m odd case gen case}
    Let $m, M$ be integers with $m\geq 3$ odd and $M=(m-1)/2$. Then, for any $\ell$ with $0 \leq \ell \leq M$, and any even integer $n\geq M$, there exist coefficients $(a_{j,\ell}^{(m)}(n))_{0\leq j \leq N_\ell}$, where $N_\ell = Mn+\ell$, such that
    \begin{align*}                                            
        H_{n,\ell}^{(m)}(z) = \sum_{j=0}^{N_\ell}  a_{j,\ell}^{(m)}(n)\frac{T_{n+2j}(z)}{j!^2}.
    \end{align*}
    Furthermore, for $j=0,\dots,N_\ell$, we have $a_{j,\ell}^{(m)}(n) \in \mathbb{Z}_{>0}$ and
    \begin{align*}
        \limsup_{\substack{n\to\infty \\ \textrm{$n$ even}}} \max_{0\leq j\leq N_\ell}\big\{|a_{j,\ell}^{(m)}(n)|^{1/n}\big\} \leq \limsup_{n\to\infty} \max_{0\leq j\leq N_\ell}|a_{j}^{(m)}(n)|^{1/n} \leq   (2M)^M M^{M}.                                                     
    \end{align*}

The condition $n$ even in Proposition~\ref{prop: rec coeff H^m even case gen case} is sufficient for our purpose. In order to treat the case of odd indices $n$, we would need to be able to express a product $T_{n+2j}(z)T_{2\ell}(z)$ in terms of $T_{n+2i+2j}$. We did not do it in order to keep arguments as short as possible. However, curious readers may try to prove that
\begin{align*}
    \frac{T_{2n+1}(z)}{(2n+1)!}\frac{T_{2\ell}(z)}{\ell!^2} = \sum_{k=0}^{\ell} \binom{n+1/2+\ell}{2\ell-k} \binom{n+k}{k} \binom{2\ell-k}{\ell} 4^k \frac{T_{2n+1+2k}(z)}{(2n+1+2k)!}.
\end{align*}

\label{prop: first estimates of b_s,k}
    Let $s\geq 2$ be an integer and $p$ be a prime number. For any integer $k\geq 0$, we have
    \begin{align*}
        \frac{(2k+1)!}{k!^2}|b_{s,k}| &\le (4(k+1))^{s},\\
        (d_{k+1}d_{2k+1})^{s/2} b_{s,k}&\in\mathbb{Z} \quad \textrm{and} \quad |b_{s,k}|_p \leq p^{(s+1)\log_p(2k+1)}.
    \end{align*}

Write $s = 2+i+2t$, where $i\in\{0,1\}$ and $t=\lfloor (s-2)/2\rfloor$. Let $k\geq t$ be integer. The set $J_t(k)$ of $(t+1)$--tuples $(j_0,\dots,j_t)\in\mathbb{Z}_{\geq 0}^{t+1}$ such that $j_0+\cdots+ j_t = k-t$ is bounded from above by $(k+1)^{t+1}$ (since for each such tuple satisfies $0\leq j_0,\dots,j_t \leq k$). Given $(j_0,\dots,j_t)\in J_t(k)$, we have (using the estimate $\binom{2n+1}{n+1} \geq 2^{2n+1}/(2n+2) = 4^n /(n+1)$)
    \begin{align}\label{eq proof: estimate b_s,j}
        \frac{j_i!^2}{(j_i+1)(2j_i+1)!} = \frac{1}{(j_i+1)^2} \binom{2j_i+1}{j_i+1}^{-1} \leq \frac{4}{(j_i+1)4^{j_i+1}}
    \end{align}
    for $i=0,\dots,t$. Hence, since $(j_0+1)+\cdots + (j_t+1)= k+1$,
    \begin{align*}
        (j_t+1)\prod_{i=0}^{t}\frac{j_i!^2}{(j_i+1)(2j_i+1)!} \leq \frac{4^{t+1}}{4^{k+1}},
    \end{align*}
    and we deduce, in view of \eqref{eq: eq b_s,k, s odd} and \eqref{eq: eq b_s,k, s even}, that $ |b_{s,k}| \leq (4(k+1))^{t+1} / 4^{k+1}$. We conclude by using the crude upper bound $(2k+1)!/k!^2 \leq (k+1)\binom{2k+1}{k} \leq (k+1)4^{k+1}$ (and by noting that $t+2\leq s$).

    \medskip

    Let $(j_0,\dots,j_t)\in J_t(k)$. Eq.~\eqref{eq: denom Prevost inverse binomial} combined with \eqref{eq proof: estimate b_s,j} ensures that $(d_{k+1}d_{2k+1})^{t+1}b_{s,k}$ is an integer. Since $2(t+1) \leq s$ and $d_{k+1}$ divides $d_{2k+1}$, we find the crude upper bound
    \begin{align*}
        |b_{s,k}|_p \leq |d_{2k+1}|_p^{-s} \leq p^{s\log_p (2k+1)}.
    \end{align*}
    (we used the formula $|d_N|_p = p^{-\lfloor \log_p(N) \rfloor}$ for the last inequality).

\label{thm: lcm multinom coeff}
    Let $K,r$ be positive integers. Then
    \begin{align*}
        d(r,K) = \prod_{j=1}^{r-1} \frac{d_{\lfloor(K+r-1)/j\rfloor}}{K+j}.
    \end{align*}

\label{cor: lcm multinom coeff}
    Let $k,t$ and $j_0,\dots,j_t\geq 0$ be non-negative integers with $k\geq t$ and $j_0+\cdots + j_t = k-t$. Then
    \begin{align*}
        \left(\prod_{j=1}^{t} d_{\lfloor k/j\rfloor}\right) \frac{\prod_{i=0}^{t} j_i!}{k!}  \in \mathbb{Z}.
    \end{align*}

According to Theorem~\ref{thm: lcm multinom coeff} with $K=k-t$ and $r=t+1$, the integer
    \begin{align*}
        \frac{k!}{\prod_{i=0}^{t} j_i!} = \binom{k-t}{j_0,\dots,j_t} \prod_{j=1}^{t}(k-t+j),
    \end{align*}
    divides $\prod_{j=1}^{t} d_{\lfloor k/j\rfloor}$.

Let $k\ge 0$ be an integer and $\alpha \in \mathbb{C}$. Then \cite[Lemma~7.8]{KP2} implies that
    \begin{align}\label{estimate binomial}
        \frac{|(\alpha)_k|}{k!} \le (ek)^{|\alpha|},
    \end{align}
    (where $e = \exp(1)$). Let $x \in \mathbb{Q} \setminus \mathbb{Z}_{\le 0}$. By \eqref{estimate binomial} we have
    \begin{align*}
        \max_{0\leq k \leq N} \left|\dfrac{(x)_{k}}{k!}\dfrac{(1-x)_{k}}{k!}\right| \leq (eN)^{2|x|+1}.
    \end{align*}
    Combined with Theorem~\ref{thm: property of the coeff of P_n}, we deduce that $\limsup_{\substack{n \to \infty \\ \textrm{$n$ even}}}|P_{m,n,\ell}(x)|^{1/n} \leq C(m)$. Now, note that for each $j,k\geq 0$ with $j\leq k-1$, we have
    \begin{align*}
        \left|\binom{k}{j+1}^{-2} \frac{(x+j+1)_{k-j-1}}{(k-j-1)!} \frac{(2+j-x)_{k-j-1}}{(k-j-1)!} \right|
        & \leq \left(\frac{(j+1)!(|x|+j+2)_{k-j-1}}{k!} \right)^2 \\
        & \leq \left(\frac{(|x|+1)_k}{k!} \right)^2 \leq (ek)^{2|x|+2},
    \end{align*}
    the last inequality coming from~\eqref{estimate binomial}. Recall that $N_\ell = Mn+\ell$. Using the expansion of $Q_{m,n,s,\ell}(z)$ provided by Theorem~\ref{thm:expansion} with the above, we get
    \begin{align*}
        |Q_{m,n,s,\ell}(x)|  & \leq \max_{1\leq k\leq N_\ell}  |p_{k,\ell}^{(m)}(n)| \sum_{k=1}^{N_\ell} \sum_{j=0}^{k-1} |b_{s,j}| \frac{(2j+1)!}{j!^2} (ek)^{2|x|+2}.

    \end{align*}
    Using Proposition~\ref{prop: first estimates of b_s,k} together with Theorem~\ref{thm: property of the coeff of P_n}, this yields $\limsup_{\substack{n \to \infty \\ \textrm{$n$ even}}}|Q_{m,n,s,\ell}(x)|^{1/n} \leq  C(m)$.

\label{den ask}
    Let $x\in \mathbb{Q}^\times$ and let $n,m,\ell, M = \lfloor(m-1)/2\rfloor$ be as at the beginning of this subsection. Define $\mathfrak{D}_m(n) = 2$ (resp. $\mathfrak{D}_m(n) = d_{n+1}$) if $m$ is odd (resp. even), and set
    \begin{align} \label{Dn(x)}

        D_n(x) &= d^2_{N} \mu_{N}(x)^2 \mathfrak{D}_m(n) \left(\prod_{j=1}^{M-1}d_{ N/j}\right)^2,
    \end{align}
    where $N=M(n+1)$. Then
    \begin{align*}
        D_n(x) P_{m,n,\ell}(x)\in \mathbb{Z} \quad \textrm{and} \quad D_n(x)Q_{m,n,s,\ell}(x)\in \mathbb{Z} \qquad (s\in S_m).
    \end{align*}
    Furthermore, we have
    \begin{align} \label{eq: asympt D_n(x)}
        \limsup_{\substack{ n \to\infty \\ \textrm{$n$ even}}} D_n(x)^{1/n} &= \mu(x)^{2M}\exp\Big(m-1 + \sum_{j=1}^{M-1} \frac{2M}{j}\Big).
    \end{align}
    If $|x|_p > 1$, we also have
    \begin{align} \label{eq: asympt D_n(x) p-adic}
        \limsup_{\substack{ n \to\infty \\ \textrm{$n$ even}}} |D_n(x)|_p^{1/n} &= |\mu(x)|_p^{2M} = |x|_p^{-2M} p^{-\frac{2M}{p-1}}.
    \end{align}

\label{den bsk}
    Given integers $t,k\geq 0$, define the integers
    \begin{align*}
        \mathfrak{D}_{0,t}(k) = 2\left(\prod_{j=1}^{t}d_{\lfloor (k+1)/ j\rfloor}\right)^2 \quad \textrm{and} \quad \mathfrak{D}_{1,t}(k) = 2^{-1}d_{\lfloor (k+1)/(t+1) \rfloor} \mathfrak{D}_{0,t}(k).
    \end{align*}
    \begin{comment}



    \end{comment}
    Then $\mathfrak{D}_{i,t}(k)$ divides $\mathfrak{D}_{i,t+1}(k)$ and $\mathfrak{D}_{i,t}(k+1)$ for $i=0,1$. Furthermore, we have
    \begin{align*}
        \mathfrak{D}_{i,t}(k)\frac{(2k+1)!}{k!^2}b_{2+i+2t,k} \in \mathbb{Z} \qquad (i=0,1).
    \end{align*}

Given $j_0, \cdots, j_t \geq 0$ be integers such that $j_0+\cdots + j_t = k-t$ and using the identity  $(j+1)(2j+1)! = (2j+2)!/2$, we find
    \begin{align*}
        \frac{(2k+1)!}{k!^2}(j_t+1)\prod_{i=0}^{t} \frac{j_i!^2}{(j_i+1)(2j_i+1)!} = K(j_0,\dots,j_t) \left(\frac{\prod_{i=0}^{t} j_i!}{k!}\right)^2,
    \end{align*}
    where $K(j_0,\dots,j_t) = 2^t \binom{2k+1}{2j_0+2,\dots,2j_{t-1}+2,2j_t+1} \in \mathbb{Z}$. Combined with Corollary~\ref{cor: lcm multinom coeff} and in view of~\eqref{eq: eq b_s,k, s even}, we obtain, as expected,
    \begin{align*}
        \mathfrak{D}_{0,t}(k)\frac{(2k+1)!}{k!^2}b_{2+2t,k}\in \mathbb{Z}.
    \end{align*}
    Let $j_0, \cdots, j_t \geq 0$ be integers satisfying $j_0+\cdots + j_t = k+1-t$. In order to estimate the denominator of $b_{3+2t,k}$, we need to study the term
    \[
        \frac{(2k+1)!}{k!^2}\prod_{i=0}^{t} \frac{j_i!^2}{(j_i+1)(2j_i+1)!}.
    \]
    By symmetry, we may assume without loss of generality that $j_0\geq \cdots \geq j_t$, so that $(t+1)(j_t+1) \leq \sum_{i=0}^{t}(j_i+1) = k+1$. By the above, we have
    \begin{align*}
        \frac{(2k+1)!}{k!^2}\prod_{i=0}^{t} \frac{j_i!^2}{(j_i+1)(2j_i+1)!}  = \frac{K(j_0,\dots,j_t)}{j_t+1}\left(\frac{\prod_{i=0}^{t} j_i!}{k!}\right)^2.                                                                           
    \end{align*}
     and using once again Corollary~\ref{cor: lcm multinom coeff}, we find $\mathfrak{D}_{1,t}(k)\frac{(2k+1)!}{k!^2} b_{3+2t,k}\in \mathbb{Z}$.

By Theorem~\ref{thm: property of the coeff of P_n} combined with \eqref{well-known}, we obtain
    \[
        \mu_{N_\ell}(x)^2P_{m,n,\ell}(x)\in \mathbb{Z}, \qquad \textrm{where } N_\ell = nM +\ell.
    \]
    For $Q_{m,n,s,\ell}(x)$, we will use the expansion~\eqref{eq thm: expansion Q_s} established in Theorem~\ref{thm:expansion}, namely
    \begin{align*}
        Q_{m,n,s,\ell}(z) = \sum_{k=1}^{N_\ell}p_{k,\ell}^{(m)}(n)\sum_{j=0}^{k-1} \frac{b_{s,j}}{(j+1)^2} \frac{(2j+1)!}{j!^2} \binom{k}{j+1}^{-2} \dfrac{(z+j+1)_{k-j-1}}{(k-j-1)!} \dfrac{(2+j-z)_{k-j-1}}{(k-j-1)!},
    \end{align*}
    (where the coefficients $p_{k,\ell}^{(m)}(n)$ are all integers according to  Theorem~\ref{thm: property of the coeff of P_n}). Eq.~\eqref{eq: denom Prevost inverse binomial} implies that
    \begin{align*}                           
        d^2_{N_\ell}\frac{1}{(j+1)^2}\binom{k}{j+1}^{-2} \in \mathbb{Z} \qquad \text{for} \ 1\le k \le N_\ell \quad \textrm{and} \quad \ 0\le j \leq k-1.
    \end{align*}
    Combined with Lemma~\ref{den bsk} and~\eqref{well-known}, we finally find, writing $s=2+i+2t$ with $i\in\{0,1\}$ and $t\geq 0$,
    \begin{align*}
        d^2_{N_\ell} \mu_{N_\ell}(x)^2 \mathfrak{D}_{i,t}(N_\ell-1) Q_{m,n,s,\ell}(x) \in \mathbb{Z}.
    \end{align*}
    The upper bound $s\leq m-1$ yields $t\leq \lfloor (m-3)/2 \rfloor = M-1$. On the other hand $N_\ell \leq nM+M = (n+1)M$. We deduce that $\mathfrak{D}_{i,t}(N_\ell-1)$ divides
    \begin{align*}
         \mathfrak{D}_{i,M-1}((n+1)M-1) = \mathfrak{D}_m(n) \left(\prod_{j=1}^{M-1}d_{ M(n+1)/j}\right)^2.
    \end{align*}
    Estimate \eqref{eq: asympt D_n(x)} follows from $\mu_N(x)^{1/N}\sim \mu(x)$ together with $d_N^{1/N} \sim e$ as $N$ goes to infinity (this is a consequence of the prime number theorem).\\
    To get \eqref{eq: asympt D_n(x) p-adic}, it suffices to notice that $|d_k|_p = p^{-\lfloor \log_p(k) \rfloor} = p^{o(k)}$ as $k$ tends to infinity, and that $|\mathrm{den}(x)|_p = |x|_p^{-1}$ under the assumption $|x|_p > 1$.

\label{remainder est}
    Let $p$ be a prime number and let $x\in \mathbb{Q}$ be such that $|x|_p > 1$. Let $m \geq 3$ be an integer. For each $s\in S_m$ and  $\ell= 0,\dots,M:= \lfloor (m-1)/2 \rfloor$, the series $\mathfrak{R}_{m,n,s,\ell}(x)$ converges in $\mathbb{Q}_p$, and
    \begin{align*}
        \limsup_{\substack{n\to\infty\\ \textrm{$n$ even}}}\big|\mathfrak{R}_{m,n,s,\ell}(x)\big|_p^{1/n} \le p^{-\tfrac{2}{p-1}}  |x|^{-2}_p.
    \end{align*}

Fix integers $s,\ell,n \geq 0$ with $n$ even, $s\in S_m$ and $0 \le \ell \le M$. For $k\geq n$, we set
    \[
        C_k(t) = (2t+n-1) (t+n)_{k-n}(1 - t)_{k-n} \frac{(t)^m_n}{n!^m} \widetilde{A}_\ell(t + n/2),
    \]
    where
    \begin{align*}
        \widetilde{A}_\ell(z) =
        \begin{cases}
            (z-n/2)_\ell (1-z-n/2)_\ell & \textrm{if $m$ is even},\\
            (z-\ell)_{2\ell} & \textrm{if $m$ is odd},
        \end{cases}
    \end{align*}
    and define $c(k) = \deg(C_k) = mn+2(k-n+\ell)+1$. Note that $\widetilde{A}_\ell(z) = n!^{m-1}A_\ell(z)$, where the polynomial $A_\ell(z)$ is as in Definition~\ref{def: construction Pade approximants, choice of A_ell}). Since $n$ is even, we have $\widetilde{A}_\ell(t+n/2)\in \mathbb{Z}[t]$. According to~\eqref{eq thm: expansion remainder R_s} of Theorem~\ref{thm:expansion}
    \begin{align*}
        \mathfrak{R}_{m,n,s,\ell}(z) & = \dfrac{n!^2}{2}\sum_{k=n}^{\infty} \binom{k}{n} \dfrac{r_{k,s}}{(z)_{k+1}(1-z)_{k+1}}, \qquad\textrm{where } r_{k,s}=\sum_{j=0}^{c(k)} a_{s,j}\cdot \mathrm{Eval}_{t=0}\circ \boldsymbol{\Delta}_{-1}^j (C_{k}(t)).
    \end{align*}
    Let $k \ge n$ be an integer and $j\in\{0,\dots,c(k)\}$. Since the polynomial $T(t) := (t)_n^m /n!^m$ satisfies $T(\mathbb{Z})\subseteq \mathbb{Z}$, we clearly have $\mathrm{Eval}_{t=0}\circ \boldsymbol{\Delta}_{-1}^j (C_{k}(t)) \in \mathbb{Z}$. Eq.~\eqref{eq: a_s,k expressed as Z-linear combination of b_s,k} combined with Proposition~\ref{prop: first estimates of b_s,k} implies that
    \begin{align*}
        |2r_{k,s}|_p \leq \max_{0\leq i \leq \lfloor c(k)/2 \rfloor}\{ |b_{s,i}|_p \} \leq p^{(s+1)\log_p(2c(k)+1)} = p^{\mathcal{O}(\log k)}
    \end{align*}
    where the implicit constant in $\mathcal{O}(\log k)$ depends on $n$ and $m$. Together with
    \begin{equation*}
        \left|\frac{n!^2}{(x)_{k+1}(1-x)_{k+1}} \right|_p \left|\binom{k}{n}\right|_p  \le |n!|_p^2 |x|_p^{-2(k+1)} \leq p^{-2k},
    \end{equation*}
    this yields the convergence of the series $\mathfrak{R}_{m,n,s,\ell}(x)$ in $\mathbb{Q}_p$. Moreover
    \begin{align*}
        \bigl|2\mathfrak{R}_{m,n,s,\ell}(x)\bigr|_p   \le
           |n!|_p^2 \, |x|_p^{-2n} \cdot \max_{k \ge n} \left\{p^{(s+1)\log_p(c(k))}|x|_p^{-2(k-n+1)} \right\}
         = e^{o(n)}\, |n!|_p^2 \, |x|_p^{-2n},
    \end{align*}
    as $n$ tends to $\infty$. We conclude by raising both sides to the power $1/n$ and by using the classical estimate
    \[
    \lim_{n \to \infty} |n!|_p^{\,1/n}
       \le p^{-\tfrac{1}{p-1}}.
    \]

\label{main theorem: general version}
    Let $p$ be a prime number and $x\in \mathbb{Q}$ with $|x|_p>1$. Let $m\ge 3$ be an integer such that
    \begin{align} \label{hyp p,x}
         f(m) < 2(M+1)\Big(\log|x|_p+\dfrac{\log p}{p-1}\Big) - 2M\log \mu(x).
    \end{align}
    Then, writing $S_m = \{s_1,\dots,s_M\}$, the $M+1$ elements $1$, $F_{s_1}(x)$, $\dots$, $F_{s_M}(x)\in \mathbb{Q}_p$ are linearly independent over $\mathbb{Q}$.

\label{thm: linear indpce generic values}
    Let $p$ be a prime number and $x\in \mathbb{Q}$ with $|x|_p>1$, and fix an integer $m\ge 3$. Let $I$ be an infinite subset of $\mathbb{Z}_{\geq 0}$, and let $\beta,\rho_\infty,\rho_p,\delta$ be real numbers and $(D_n)_{n\geq 0}$ be a sequence of positive integers such that, for each $s\in S_m$ and each $\ell=0,\dots,M$,
    \begin{align*}
        & D_n P_{m,n,\ell}(x), \; D_n Q_{m,n,s,\ell}(x) \in \mathbb{Z} \quad \textrm{and} \quad  \limsup_{\substack{n\to\infty \\ n\in I}} \max\big\{|P_{m,n,\ell}(x)|, |Q_{m,n,s,\ell}(x)|\big\}^{1/n} \leq e^\beta, \\
        & \limsup_{\substack{n\to\infty \\ n\in I}} D_n^{1/n} \leq e^{\rho_\infty} \quad \textrm{and} \quad \limsup_{\substack{n\to\infty \\ n\in I}} |D_n|_p^{1/n} \leq e^{-\rho_p}, \\
        & \limsup_{\substack{n\to\infty \\ n\in I}} |\mathfrak{R}_{m,n,s,\ell}(x)|_p^{1/n} \leq e^{-\delta}.
    \end{align*}
    Suppose that $\beta+\rho_\infty < \delta + \rho_p$. Then the $M+1$ elements $1$, $F_{s_1}(x)$, $\dots$, $F_{s_M}(x)\in \mathbb{Q}_p$ are linearly independent over $\mathbb{Q}$.

The proof is classical, see for example \cite[Proposition $5.7$]{DHK2} (in the case $K=\mathbb{Q}$, $v_0=p$), which also provides an effective irrationality measure result, or \cite[Theorem 11.4]{KP2}. For the sake of completion we recall the arguments.\\
    By contradiction, suppose that the coordinates of the $(M+1)$--tuple $(1,F_{s}(x))_{s\in S_m}$ are linearly dependent over $\mathbb{Q}$. Then, there exists $(b,b_{s})_{s\in S_m}\in\mathbb{Z}^{M+1}\setminus\{\boldsymbol{0}\}$ such that
    \begin{align}
        \label{eq proof: main thm: eq1}
        b+\sum_{s \in S_m} b_{s} F_{s}(x) = 0.
    \end{align}
    Given $n\in I$, define the integers $\widehat{p}_{m,n,\ell} := D_nP_{m,n,\ell}(x)$ and $\widehat{q}_{m,n,s,\ell} := D_n Q_{m,n,s,\ell}(x)$ for each $\ell=0,\dots,M$. Theorem~\ref{non zero det} implies that the $(M+1)\times (M+1)$ matrix whose columns are $(\widehat{p}_{m,n,\ell}, \widehat{q}_{m,n,s,\ell})_{s\in S_m}$ for $\ell=0,\dots,M$,

    is non-singular. Consequently, there exists an integer $\ell$ with $0\leq \ell \leq M$ such that
    \begin{align*}
        K_n = K_n(\ell) := b \widehat{p}_{m,n,\ell} + \sum_{s\in S_m} b_{s} \widehat{q}_{m,n,s,\ell} \textrm{ is a non-zero integer.}
    \end{align*}
    By hypothesis, we have $\limsup_{\substack{n\to \infty \\ n\in I}} |K_n|^{1/n} \leq e^{\beta + \rho_\infty}$. On the other hand, writing
    \begin{align*}
        K_n = K_n - \widehat{p}_{m,n,\ell}\Big(b+\sum_{s \in S_m} b_{s} F_{s}(x)\Big)                                                                                
         = \sum_{s \in S_m} b_{s} D_n \mathfrak{R}_{m,n,s,\ell}(x),
    \end{align*}
    we find $\limsup_{\substack{n\to \infty \\ \textrm{$n\in I$}}}|K_n|_p^{1/n} \leq e^{-\rho_p-\delta}$. Since $|K_n||K_n|_p\geq 1$, it follows that $\beta + \rho_\infty \geq \delta + \rho_p$, a contradiction.

Denote by $I$ the set of positive even integers. Let $n$ be an integer and denote by $D_n(x)$ the integer defined as in Proposition~\ref{den ask}. According to the aforementioned proposition, $D_n(x)P_{m,n,\ell}(x)$ and $D_n(x) Q_{m,n,s,\ell}(x)$ are integers, and
    \begin{align*}
        \limsup_{\substack{n\to\infty \\ n\in I}} D_n^{1/n} \leq e^{\rho_\infty} \quad \textrm{and} \quad \limsup_{\substack{n\to\infty \\ n\in I}} |D_n|_p^{1/n} \leq e^{-\rho_p},
    \end{align*}
    where,
    \begin{align*}
        \rho_\infty &= 2M\log\mu(x) + (m-1) + \sum_{j=1}^{M-1}\frac{2M}{j}, \\
        \rho_p &= 2M\left(\log |x|_p+\frac{\log p}{p-1}\right).
    \end{align*}
    On the other hand Proposition~\ref{prop: estimate Pade via auxiliary seq} yields
    \[
        \limsup_{\substack{n \to \infty \\ n\in I}}  \max_{s\in S_m}
        \bigl\{|P_{n,\ell}(x)|,\, |Q_{n,s,\ell}(x)| \bigr\}^{1/n} \le e^\beta,\qquad \textrm{where } \beta = \log(C(m)).

    \]
    where $C(m)$ is as in the statement of Theorem~\ref{thm: property of the coeff of P_n}. In the case $m=4$ and $m=6$, we may take $\beta=0$, see Proposition~\ref{prop: estimate Pade via m=4 and m=6, Perron rec}. Finally, Proposition~\ref{remainder est} yields
    \begin{align*}
        \limsup_{\substack{n\to \infty \\ n \in I}} |\mathfrak{R}_{m,n,s,\ell}(x)|_p^{1/n} \leq e^{-\delta}, \qquad \textrm{where } \delta =
        \ 2\Big(\log|x|_p+\dfrac{\log p}{p-1}\Big).
    \end{align*}
    We conclude by Theorem~\ref{thm: linear indpce generic values}.

Let $p$ be a prime number and $s\geq 2$ be an integer. Combining \eqref{eq: link zeta_p and derivative of G_p} of Lemma~\ref{expansion zeta_p} with Lemma~\ref{lem: series expansion Theta_s and R_s} and, we find for any $x\in \mathbb{Q}_p$ with $|x|_p > 1$:
    \begin{align*}
        \frac{ (-1)^{s-1}\omega(x)^{s-1}}{(s-1)!} R_s(x) &=\zeta_p(s,x),
    \end{align*}
    where                                                                                   
    $\omega$ denotes the Teichmüller character (see Section~\ref{section: notation}). Furthermore, writing $x = a/p^r$ with $|a|_p = 1$ and $r\in\mathbb{Z}_{\geq 1}$, we have
    \begin{align*}
        \omega\left(\frac{x+1}{2} \right) = p^{-r}\omega\left(\frac{a+p^r}{2} \right) =  p^{-r}\omega\left(\frac{a}{2} \right) =  \omega\left(\frac{x}{2} \right).
    \end{align*}
    So, combining the above with Lemma~\ref{identities}~\ref{assertion identities 5}, we also deduce that
    \begin{align*}
        \frac{ (-2)^{s-1}\omega(x/2)^{s-1}}{(s-1)!}\Theta_s(x) = \zeta_p\left(s,\frac{x+1}{2}\right) - \zeta_p\left(s,\frac{x}{2} \right),
    \end{align*}
    Taking $x = p^{-r}$ (resp. $x = 2p^{-r}$) with $r\geq \mathbb{Z}_{\geq 1}$, we have $\omega(x) = p^{-r}\in\mathbb{Q}$ (resp. $\omega(x/2) = p^{-r} \in \mathbb{Q}$). Consequently, there exists $\lambda_s,\mu_s\in\mathbb{Q}^\times$ such that
    \begin{align*}
        \zeta_p(s,p^{-r}) = \lambda_s R_s(p^{-r})   \quad \textrm{and} \quad \zeta_p(s,p^{-r} + 1/2) - \zeta_p(s,p^{-r}) = \mu_s\Theta_s(2p^{-r}).
    \end{align*}
    We conclude by applying Theorem~\ref{main theorem: general version} with $x=p^{-r}$ for even $m$ (resp. $x=2p^{-r}$ for odd $m$), and by using the identities
    \[
        |p^{-r}|_p = |2p^{-r}|_p =p^r \quad \textrm{and} \quad \mu(p^{-r}) = \mu(2p^{-r}) = p^{r+\tfrac{1}{p-1}}.
    \]

According to \cite[Proposition 5.2]{B}, we have
    \begin{align*}
        R_3(1/4) &= 4^3\zeta_2(3) \qquad (\textrm{for $p=2$}),\\
        R_3(1/3) &= 3^3\zeta_3(3) \qquad (\textrm{for $p=3$})
    \end{align*}
(note that in \cite{B}, we have $T(z) = R_3(z)$ and $T_p(x)$ denotes the $p$-adic series $R_3(x)$). Theorem~\ref{main theorem: general version} with $m=4$, $p=2$ and $x=1/p^2$ (resp. $p=3$ and $x=1/p$) yields $R_3(1/4)\in \mathbb{Q}_2\setminus \mathbb{Q}$ (resp. $R_3(1/3)\in\mathbb{Q}_3\setminus\mathbb{Q}$).

\label{prop: estimate Pade via m=4 and m=6, Perron rec}
    Let $x \in \mathbb{Q}$ and $m\in\{4,6\}$.  For each integer $\ell= 0,\dots, M:= (m-2)/2$, we have
    \[
        \limsup_{n \to \infty } \max_{s\in S_m}
        \bigl\{ |P_{n,\ell}(x)|,\, |Q_{m,n,s,\ell}(x)| \bigr\}^{1/n}
        \le  1.
    \]

Once we know that a recurrence \eqref{eq: matrix rec relation 1} exists, finding the coefficients of $A(n)$ becomes a pure problem of linear algebra. We may also deduce from the recurrence \eqref{eq: matrix rec relation 1} a Poincaré-Perron recurrence of the form
    \begin{align*}
        Z_{n+1,s} = A(n,z)Z_{n,s} \qquad (n\geq 2).
    \end{align*}
    where $ Z_{n,s} = {}^t \Big(Q_{n,s,M-1}(z),\dots, Q_{n,s,0}(z), Q_{n-1,s,M-1}(z),\dots, Q_{n-1,s,0}(z)\Big)$, and $A(n,z)$ is a $2M \times 2M$ matrix whose coefficients are rational polynomials in $z$.

It suffices to treat the case $s=\infty$, since for each $s\in S_m$
    \begin{align*}
        Q_{n,s,\ell}(z) = \varphi_s\left(\frac{P_{n,\ell}(z)-P_{n,\ell}(t)}{z-t} \right) \quad \textrm{and} \quad  T_2(z)Q_{n,s,\ell}(z) = \varphi_s\left(\frac{T_2(z)P_{n,\ell}(z)- T_2(t)P_{n,\ell}(t)}{z-t} \right),
    \end{align*}
    (the last equality coming from the fact that $(T_2(z)-T_2(t))P_{n,\ell}(t)/(z-t) \in \ker \varphi_s$ by \eqref{eq: simplified kernel useful for proof}).\\
    The polynomials $\{P_{k,0}(z),\dots,P_{k,M-1}(z)\}_{0 \leq k < n}$ form a basis of $V_1 \cap \mathbb{Q}[z]_{< 2Mn}$, where the eigenspace $V_1 = \{ f \;;\; f(z) = f(1-z)\}$ is defined as in Section~\ref{involution}. In particular, given $\ell\in\{0,\dots,M-1\}$, there exist coefficients $\lambda_{i,j}\in \mathbb{Q}$, such that,
    \begin{align}
        T_{2}(z) P_{n,\ell}(z) & = \lambda_{n+1,0} P_{n+1,0}(z) + \sum_{i=0}^{n} \sum_{j=0}^{M-1} \lambda_{i,j} P_{i,j}(z).  \label{eq: expansion for rec 1}
    \end{align}
    Considering the degree of $T_{2}(z) P_{n,\ell}(z)$, we must have $\lambda_{n+1,0}\neq 0$ if $\ell=M-1$. Similarly, if $\ell < M-1$, then $\lambda_{n+1,0} = \lambda_{n,M-1} = \cdots = \lambda_{n,\ell+2} = 0$ and $\lambda_{n,\ell+1}\neq 0$. So, it just remains to prove that
    \begin{align} \label{eq proof: rec matrix inter}
        \lambda_{i,j} = 0 \qquad \textrm{for $i = 0,\dots,n-2$ and $0\leq j < M$}.
    \end{align}
    According to \eqref{eq: simplified kernel useful for proof}, for each integer $i$ with $i\geq k+1$
    \[
        T_{2k+1}(t)P_{i,j}(t) \in \bigcap_{s\in S_m} \ker \varphi_s \qquad (0\leq j < M).
    \]
    Let $k\in\{0,\dots,n-2\}$ and suppose that for each $i$ in $\{0,\dots,k-1\}$, we have $\lambda_{i,0} = \cdots =\lambda_{i,M-1} = 0$ (if $k=0$, this is automatic). Multiplying  each side of \eqref{eq: expansion for rec 1} by $T_{2k+1}(t)$, and since for $i=k+1,\dots,n+1$ and $j=0,\dots,M-1$, Eq.~\eqref{eq: simplified kernel useful for proof} yields
    \[
        T_{2k+1}(t)T_2(t)P_{n,\ell}(t) \in \bigcap_{s\in S_m} \ker \varphi_s \quad \textrm{and} \quad T_{2k+1}(t)P_{i,j}(t) \in \bigcap_{s\in S_m} \ker \varphi_s,
    \]
    we deduce that,
    \begin{align*}
        0 = & \sum_{j=0}^{M-1} \lambda_{k,j}\varphi_s\Big(T_{2k+1}(t) P_{k,j}(z)\Big).
    \end{align*}
    By Corollary~\ref{cor: non-sing matrix, useful for rec}, this yields $\lambda_{k,j} =0$ for $j=0,\dots,M-1$. Hence \eqref{eq proof: rec matrix inter}.

\label{prop: case ell = M}
    Let $m\geq 3$ be an integer. There exist an integer $d\geq 0$ and $(q_i(n))_{n\geq 2M}$ satisfying $q_i(n) = \mathcal{O}(n^d)$ for $i=0,\dots,M$, such that for each $s\in S_m \cup \{\infty\}$ and each $n\geq 2M$,
    \begin{align*}
        Q_{n,s,M}(z) = q_M(n) Q_{n+1,s,0}(z) + \sum_{i=0}^{M-1} q_{i}(n) Q_{n,s,i}(z).
    \end{align*}
    In particular, for each $x\in\mathbb{Q}$, we have
    \begin{align*}
        \limsup_{n\to\infty} |Q_{n,s,M}(x)|^{1/n} \leq \max_{0\leq \ell < M} |Q_{n,s,\ell}(x)|^{1/n}.
    \end{align*}

In view of the definition of $Q_{m,n,s,\ell}(z)$ (for $s\in S_m$), it suffices treat the case of $s=\infty$. We denote by $A_{n,\ell}(z)$ the polynomial $n!^{m-1}A_\ell(z)$ of Definition~\ref{def: construction Pade approximants, choice of A_ell}. Writing $\varepsilon = (-1)^{m-1}$, we have
    \begin{align}\label{eq proof: inter technique 0}
        R_\varepsilon(T_{n+1}(z)^m) = T_n(z)^m Q_n(z), \qquad \textrm{where }  Q_n(z) = \frac{\left(z+\frac{n}{2} \right)^m - \left(1-z+\frac{n}{2}\right)^m}{2z-1} \in V_1 \cap \mathbb{Q}[z].
    \end{align}
    The polynomial $Q_n(z)\in V_1$ has degree $2M$, and $A_{n,0}(z),\dots, A_{n,M}(z)$ form a basis of $V_1 \cap \mathbb{Q}[z]_{\leq 2M}$, so there exist coefficients  $\lambda_\ell(n)\in \mathbb{Q}$ for $\ell=0,\dots,M$, with $\lambda_M(n)\neq 0$, such that
    \begin{align}\label{eq proof: inter technique}
        Q_n(z)  = \sum_{\ell=0}^{M} \lambda_\ell(n) A_{n,\ell}(z).
    \end{align}
    Note that we can easily compute $\lambda_M(n)$ by looking at the leading coefficients: we find $\lambda_M(n) = 1$ is $m$ if odd, and $\lambda_M(n) = m(n+1)/2$ when $m$ is even. More generally, we can find the coefficients $\lambda_\ell(n)$ by induction. Suppose first that $m$ is even and $n\geq 2M$. Then $0,-1,\dots,-(\ell-1)$ are simple roots of $A_\ell(z+n/2)$ and $A_\ell(-\ell+n/2)\neq 0$. Therefore,
    \begin{align*}
        \lambda_\ell(n) = A_{n,\ell}\left(-\ell + \frac{n}{2}\right)^{-1}\left( Q_n\left(-\ell + \frac{n}{2}\right) - \sum_{j=0}^{\ell-1} \lambda_\ell(n) A_{n,j}\left(-\ell + \frac{n}{2}\right) \right) \qquad (\textrm{for } \ell=0,\dots,M).
    \end{align*}
    The above relation implies that there exist absolute constants $d,C>0$ such that
    \begin{align*}
        |\lambda_\ell(n)| \leq C n^d.
    \end{align*}
    When $m$ is odd, the reasoning is similar (we evaluate at $z = \ell$ instead of $z = -\ell+n/2$). By definition of the polynomials $P_{m,n,\ell}(z)$, Eqs.~\eqref{eq proof: inter technique 0} and~\eqref{eq proof: inter technique} implies that
    \begin{align*}
        P_{m,n+1,0}(z) = R_\varepsilon^{n+1}\left((n+1)!^{-m+1}T_{n+1}(z)^m \right) & =  R_\varepsilon^{n}\left((n+1)!^{-m+1}\sum_{\ell=0}^{M} \lambda_\ell(n) A_{n,\ell}(z)T_{n}(z)^m \right) \\
        & = \sum_{\ell=0}^{M} \lambda_\ell(n) \left(\frac{n}{n+1}\right)^{m-1} P_{m,n,\ell}(z),
    \end{align*}
    and the conclusion follows easily.

We have
    \begin{align*}
        T_{2}(z)P_{n,1}(z) = \sum_{i=1}^{2n+2} b_i^{(0)}(n) \frac{T_{2i}(z)}{i!^2} \quad \textrm{and} \quad
        T_{2}(z)P_{n+1,0}(z) = \sum_{i=1}^{2n+3} b_i^{(1)}(n) \frac{T_{2i}(z)}{i!^2}
    \end{align*}
    where for $i=0,\dots,2n+1$, resp. $i=0,\dots,2n+2$,
    \begin{align*}
        b_{2n+2-i}^{(0)}(n) &= \sum_{j=\max\{0,i-1\}}^{i} (2n+2-i) a_{2n+1-j,1}^{(6)}(n) \binom{2n+2-j}{i-j}\binom{2n+2-i}{j+1-i},\\
        \textrm{resp. } b_{2n+3-i}^{(1)}(n) &= \sum_{j=\max\{0,i-1\}}^{i} (2n+3-i) a_{2n+2-j,0}^{(6)}(n+1) \binom{2n+3-j}{i-j}\binom{2n+3-i}{j+1-i}.
    \end{align*}
